// A script interpreter writing the state file (node -e, python -c, ...) is a
// rewrite even without a shell redirect.
export const SCRIPTED_WRITE = /(^|[\s;|&(])(node|python3?|ruby|perl|deno|bun)\s+(-e|-c|--eval)\b/;

// How the AI can call the CLI: `piezas`, `piezas@<version>` (npx), the
// scoped name, `node …/piezas.mjs`, `node …/index.js`, and `npm exec piezas --`
// (the `--` before the command).
export const PIEZAS_INVOCATION = String.raw`(?:\bpiezas(?:\.mjs)?(?:@[^\s"'/]+)?|@piezas\/cli(?:@[^\s"']+)?|\bindex\.js)["']?\s+(?:--\s+)?`;
// Approval is the customer's decision. The agent may never record it; the
// UserPromptSubmit hook records it from the customer's own typed message.
export const AGENT_APPROVE = new RegExp(`${PIEZAS_INVOCATION}phase\\s+approve\\b`);
// Same for an imported app's choices: the owner's reply records them.
export const AGENT_IMPORT_CHOOSE = new RegExp(`${PIEZAS_INVOCATION}import\\s+choose\\b`);

// Deleting an app is the owner's decision, made deliberately from their own
// terminal. The hooks only see the AI's tool calls, so a person's own
// `npx piezas undeploy` is unaffected.
export const AGENT_DELETE = new RegExp(`${PIEZAS_INVOCATION}(?:undeploy\\b|deploy\\b[^\\n;|&]*?(?:--delete\\b|\\sdelete(?=\\s|$)))`);
export const HTTP_DELETE = /(?:-X\s*|--request[\s=]+|--method[\s=]+|method\s*[:=]\s*['"`])DELETE\b/i;
// Secret values must never pass through the AI: a chat transcript can be kept
// for a long time. The AI names what is missing; the person sets the value.
export const AGENT_ENV_SET = new RegExp(`${PIEZAS_INVOCATION}env\\s+set\\b`);
export const AGENT_ENV_FLAG = new RegExp(`${PIEZAS_INVOCATION}(?:deploy|init)\\b[^\\n;|&]*?(?:--env[\\s=]+[A-Za-z_][A-Za-z0-9_]*=|--key[\\s=]+\\S)`);

// The status, logs and --owner-items forms of deploy do not deploy.
export const AGENT_DEPLOY = new RegExp(`${PIEZAS_INVOCATION}deploy\\b([^\\n;|&]*)`);
export const DEPLOY_READ_ONLY = /--status\b|--logs\b|--owner-items\b|(?:^|\s)(?:status|logs)(?=\s|$)/;
// deployReadOnlyCommand — the WHOLE command is one read-only deploy call
// (--status, --logs, --owner-items): no chain (&&, ;, |, a background &, a
// new line), no command substitution, no comment, no second piezas call. Its
// arguments are read the way the CLI reads them, so `--app status` is a
// deploy. Otherwise the deploy in it is judged as a deploy.
export function deployReadOnlyCommand(command) {
  const text = String(command || '');
  if (/&&|\|\||[;|\n`#]|\$\(|(?<!>)&(?!>)/.test(text)) return false;
  const calls = text.match(new RegExp(PIEZAS_INVOCATION, 'g')) ?? [];
  if (calls.length !== 1) return false;
  const call = AGENT_DEPLOY.exec(text);
  if (!call) return false;
  const words = (call[1].match(/"[^"]*"|'[^']*'|\S+/g) ?? []).filter((w) => !/^\d*>/.test(w));
  const { flags, positional } = parseCliArgs(words.map((w) => w.replace(/^(["'])(.*)\1$/, '$2')));
  const [word, ...rest] = positional;
  if (word === undefined) return Boolean(flags.status || flags.logs || flags.ownerItems);
  return (word === 'status' && rest.length === 0) || (word === 'logs' && rest.length <= 1);
}

export const DELETE_BLOCK =
  'Piezas: deleting or taking down an app is something only the owner can do, from their own terminal ' +
  '(`npx piezas undeploy`, or the app page on the Piezas console), because it cannot be undone and the people using ' +
  'the app lose it. Do not do it yourself. If they want to, tell them those two places in one sentence.';
export const ENV_SET_BLOCK =
  'Piezas: setting values (keys, passwords, settings) is something the owner does themselves, never through this chat, ' +
  'because a chat can be kept for a long time. Run `piezas env check` to list what is missing by NAME, then tell them ' +
  'where to set each one: the app page on the Piezas console (Hosting -> Environment), or `npx piezas env set NAME=...` ' +
  'in their own terminal. Never ask them to type a value here.';

// The owner's quality scan choices (qualityscan.js): never run by the AI, in
// any form (npx, node <cli>, a script that runs them).
export const AGENT_QUALITY_OWNER_RE = new RegExp(`${PIEZAS_INVOCATION}quality-scan\\s+(?:on|off|before-publishing|accept|skip)\\b`, 'i');
const QUALITY_READ_SUBS = new Set(['packet', 'verdict', 'status']);

// ownerQualityCommand — does this command run one of the owner's quality scan
// words (on, off, before-publishing, skip, accept), in any spelling the guard
// can see: quotes and backslashes taken out, words split, a $VAR, xargs,
// alias or eval near "quality-scan", or the recording functions named (even
// split in two) in an inline script.
// The owner's unattended-deploys choice (`piezas unattended on|off`): read
// the same way as the quality-scan words. "unattended" is a common word, so
// only a command that names piezas counts, and only "on" / "off" after it.
const AGENT_UNATTENDED_OWNER_RE = new RegExp(`${PIEZAS_INVOCATION}unattended\\s+(?:on|off)\\b`, 'i');
const UNATTENDED_WORDS = { re: AGENT_UNATTENDED_OWNER_RE, named: /unattended/i, exact: /^unattended$/i, read: { has: (w) => !/^(?:on|off)$/i.test(w) }, gate: /piezas/i };
const QUALITY_WORDS = { re: AGENT_QUALITY_OWNER_RE, named: /quality-?scan/i, exact: /^quality-scan$/i, read: QUALITY_READ_SUBS };
export function ownerUnattendedCommand(command) {
  return ownerChoiceCommand(command, UNATTENDED_WORDS);
}

export function ownerQualityCommand(command) {
  return ownerChoiceCommand(command, QUALITY_WORDS);
}

function ownerChoiceCommand(command, choice) {
  const text = String(command || '');
  if (choice.re.test(text)) return true;
  const flat = text.replace(/\\(.)/g, '$1').replace(/['"`]/g, '');
  if (/recordQuality|qualityOwner|appendOwner|recordQualitySkip|ownerRecord/i.test(flat.replace(/[\s+]/g, ''))) return true;
  // Words, never substrings: a path under .piezas/quality-scan/ (the packet,
  // the prompt, the findings) is something the AI reads, not the command.
  const words = flat.split(/[\s;|&()<>]+/).filter(Boolean);
  const isPath = (w) => /[/\\]/.test(w) || w.startsWith('.');
  const named = words.filter((w) => choice.named.test(w) && !isPath(w));
  if (!named.length || (choice.gate && !choice.gate.test(flat))) return false;
  // The command word, given through something the guard cannot read.
  if (/\$|\bxargs\b|\balias\b|\beval\b|\bsource\b/.test(flat)) return true;
  for (let i = 0; i < words.length; i += 1) {
    const w = words[i];
    if (!choice.named.test(w) || isPath(w)) continue;
    if (!choice.exact.test(w)) return true; // S=quality-scan, quality-scan=off, ...
    const next = words.slice(i + 1).find((x) => !x.startsWith('-'));
    if (next !== undefined && !choice.read.has(next)) return true;
  }
  return false;
}
const QUALITY_OWNER_BLOCK =
  'Piezas: turning the quality scan on or off, skipping it once, and accepting a problem it found are the owner\'s choices. ' +
  'The owner runs this command in a terminal outside their AI tool (the Terminal app works), or says it in the chat ' +
  '("quality scan off", "go live without the scan", "accept 2"). Never run it for them: ask them, in plain words, and wait for their reply.';

const UNATTENDED_OWNER_BLOCK =
  'Piezas: whether deploys with no one present may go live without the quality scan is the owner\'s choice. ' +
  'The owner runs piezas unattended on (or off) in a terminal outside their AI tool. Never run it for them: ask them, in plain words.';

export function accountActionVerdict(command) {
  if (ownerQualityCommand(command)) return guardBlock(QUALITY_OWNER_BLOCK);
  if (ownerUnattendedCommand(command)) return guardBlock(UNATTENDED_OWNER_BLOCK);
  if (AGENT_DELETE.test(command)) return guardBlock(DELETE_BLOCK);
  if (HTTP_DELETE.test(command) && /piezas/i.test(command)) return guardBlock(DELETE_BLOCK);
  if (AGENT_ENV_SET.test(command) || AGENT_ENV_FLAG.test(command)) return guardBlock(ENV_SET_BLOCK);
  return null;
}

// stripHeredocBodies — the command-level rules look at what the shell RUNS,
// not at text being written into a file (a note that mentions
// "npm install sqlite3" is not an install). File content is still checked
// against the file rules through the write targets.
export function stripHeredocBodies(command) {
  const lines = String(command || '').split('\n');
  const out = [];
  let terminator = null;
  for (const line of lines) {
    if (terminator !== null) {
      if (line.replace(/^\t+/, '') === terminator) terminator = null;
      continue;
    }
    out.push(line);
    const m = /<<-?\s*(['"]?)([A-Za-z_][A-Za-z0-9_]*)\1/.exec(line);
    if (m) terminator = m[2];
  }
  return out.join('\n');
}

export const LOCAL_DB_INSTALL = new RegExp(
  `(^|[\\s;|&(])(?:npm|pnpm|yarn|bun)\\s+(?:install|i|add)\\b[^\\n;|&]*?\\s(${LOCAL_DB_PACKAGES.map(escapeForRegExp).join('|')})(?:@[^\\s]*)?(?=\\s|$)`,
);
export const LOCAL_DB_CLI = /(^|[\s;|&(])npx\s+(?:--?\S+\s+)*(prisma|drizzle-kit|knex|sequelize-cli|typeorm)\b/;

export const HARD_NO_DB =
  'Piezas: business data lives in Piezas, never in a local database. ' +
  'Store records through @piezas/sdk (Entity Records) instead — read the `entities` rules before writing that code. ' +
  'If the owner asks for their own database, explain in plain words why Piezas keeps the records (a database inside ' +
  'the app is not protected or backed up by Piezas and can be lost when the app is updated) and recommend Piezas records; ' +
  'an app that already has one can still go live only if the owner says "deploy anyway".';

// shellWriteTargets — files a shell command writes via > / >> / tee. Ignores fd
// redirects (2>&1, >&2) and /dev/null. Best effort: it is a guard, not a parser.
export function shellWriteTargets(command) {
  const targets = new Set();
  const text = String(command || '');
  const redirect = /(?:^|[^0-9&<>])>{1,2}\s*(?!&)("[^"]+"|'[^']+'|[^\s;|&<>()]+)/g;
  let m = redirect.exec(text);
  while (m) {
    targets.add(m[1].replace(/^['"]|['"]$/g, ''));
    m = redirect.exec(text);
  }
  const tee = /(?:^|[\s;|&(])tee\s+(?:-[a-z]+\s+)*("[^"]+"|'[^']+'|[^\s;|&<>()]+)/g;
  m = tee.exec(text);
  while (m) {
    targets.add(m[1].replace(/^['"]|['"]$/g, ''));
    m = tee.exec(text);
  }
  return [...targets].filter((t) => t && t !== '/dev/null' && !t.startsWith('/dev/'));
}

// The one question the owner sees for the design sign-off (plain words, no
// machinery): the exact word "approve" is deliberate, the explanation of how it
// is recorded is for the AI only.
export const DESIGN_APPROVAL_QUESTION =
  "Here is the design preview. If you're happy with it, reply \"approve\" and I'll start building. If you want changes, tell me what to change.";

export function hardNoShellVerdict(fullCommand) {
  if (!fullCommand) return null;
  const command = stripHeredocBodies(fullCommand);
  const account = accountActionVerdict(command);
  if (account) return account;
  if (AGENT_APPROVE.test(command)) {
    return guardBlock(
      'Piezas: only the owner can approve the design, in their own words; do not run the approve command. ' +
        'Show them the preview and ask them exactly this, nothing about recording or permissions:\n' +
        `${DESIGN_APPROVAL_QUESTION}\n` +
        'Then wait. Their "approve" is recorded by the Piezas checks on its own.',
    );
  }
  if (AGENT_IMPORT_CHOOSE.test(command)) {
    return guardBlock(
      'Piezas: only the owner can choose what Piezas takes over. Do not record it yourself. ' +
        'Run `piezas import ask all`, ask the one question it prints, and wait: their reply is recorded automatically.',
    );
  }
  const install = LOCAL_DB_INSTALL.exec(command);
  if (install) return guardBlock(`${HARD_NO_DB} (blocked: installing ${install[2]})`);
  const cli = LOCAL_DB_CLI.exec(command);
  if (cli) return guardBlock(`${HARD_NO_DB} (blocked: npx ${cli[2]})`);
  return null;
}

export const PIEZAS_KEY_PUBLIC = /\b(?:NEXT_PUBLIC|VITE|PUBLIC)_[A-Z0-9_]*PIEZAS_API_KEY\b|\b(?:NEXT_PUBLIC|VITE|PUBLIC)_PIEZAS_(?![A-Z0-9_]*PUBLISHABLE)[A-Z0-9_]*(?:KEY|SECRET|TOKEN)\b/;
export const USE_CLIENT = /^\s*(?:\/\/[^\n]*\n|\/\*[\s\S]*?\*\/\s*)*\s*['"]use client['"]/;
export const PIEZAS_SECRET_LITERAL = /\bsk_(?:live|test)_[A-Za-z0-9]{12,}\b/;

export function hardNoWriteVerdict(relPath, content) {
  if (typeof content !== 'string' || !content) return null;
  const name = basename(relPath);
  const isEnvFile = name.startsWith('.env');

  if (PIEZAS_KEY_PUBLIC.test(content)) {
    return guardBlock(
      `Piezas: ${relPath} would publish the Piezas API key to the browser — a NEXT_PUBLIC_/VITE_/PUBLIC_ prefix compiles it into the page for every visitor. ` +
        'Read PIEZAS_API_KEY with no prefix, on the server only (an API route or server component).',
    );
  }
  if (!isEnvFile && PIEZAS_SECRET_LITERAL.test(content)) {
    return guardBlock(
      `Piezas: ${relPath} contains a Piezas secret key written into the code. Keys belong in .env only (and .env stays out of git). ` +
        'Read it from process.env.PIEZAS_API_KEY on the server.',
    );
  }
  if (USE_CLIENT.test(content) && /\bPIEZAS_API_KEY\b/.test(content)) {
    return guardBlock(
      `Piezas: ${relPath} is a client component ('use client') but reads PIEZAS_API_KEY. The key must stay on the server: ` +
        'move the Piezas call into an API route or a server component and pass only the data down.',
    );
  }

  const appSource = isCodeFile(relPath) && !NON_APP_DIRS.test(relPath) && !TEST_FILE_NAME.test(relPath) && !CONFIG_FILE_NAME.test(relPath);
  if (appSource) {
    const imported = LOCAL_DB_IMPORT.exec(content);
    if (imported) return guardBlock(`${HARD_NO_DB} (blocked: ${relPath} imports ${imported[1]})`);
    if (CREATE_TABLE.test(content)) return guardBlock(`${HARD_NO_DB} (blocked: ${relPath} creates a table with raw SQL)`);
  }
  if (name === 'package.json') {
    try {
      const pkg = JSON.parse(content);
      const deps = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) };
      const found = LOCAL_DB_PACKAGES.find((dep) => Object.prototype.hasOwnProperty.call(deps, dep));
      if (found) return guardBlock(`${HARD_NO_DB} (blocked: package.json adds ${found})`);
    } catch {
      // Partial JSON (an Edit fragment) — doctor judges the finished file.
    }
  }
  return null;
}

// ===========================================================================
// Sandbox: a simulated Piezas platform behind the injectable fetch
// ===========================================================================
//
// JIGSAW SEAM. `init --sandbox` marks the project (manifest.sandbox = true).
// From then on every platform call the CLI makes — create app, mint key, stage
// the hosted env, deploy, status, logs, env — is answered by this in-process
// simulator, with state in .piezas/sandbox.json. The CLI's own logic runs
// UNCHANGED: real preflight checks, real packaging, real requiredEnv gate, real
// attestation. Only the transport is fake. When Piezas sign-in for coding tools
// lands, `connect` signs in, creates the real app and drops `sandbox` — the same
// commands then reach the real platform. Anonymous downloads (the contract, the
// spec, the npm registry) still go to the network.

export const SANDBOX_STATE = 'sandbox.json';
export const SANDBOX_CONNECT_EXIT = 3;

export const SANDBOX_CREDENTIALS = Object.freeze({
  cliToken: 'sandbox-cli-token',
  tenantId: 'sandbox',
  tenantName: 'your workspace (sandbox)',
  email: 'you@sandbox.piezas.ai',
  apiBase: DEFAULT_API_BASE_URL,
  sandbox: true,
});

export const SANDBOX_NOTE =
  'SANDBOX: Piezas is simulated for this project — the app, its key, its hosted settings and its deployments ' +
  'are real-shaped but nothing is created or published. The same commands reach the real platform once the ' +
  'app is connected (Piezas sign-in for coding tools).';

export function readManifestSafe(projectDir) {
  try {
    return readJsonFile(resolve(projectDir, 'piezas.manifest.json'));
  } catch {
    return null;
  }
}

export function isSandboxProject(projectDir) {
  return readManifestSafe(projectDir)?.sandbox === true;
}

export function platformCredentials(projectDir, env) {
  if (isSandboxProject(projectDir)) return { ...SANDBOX_CREDENTIALS };
  // A sign-in for the other Piezas (production vs staging) never counts.
  if (signInMismatch(env)) return undefined;
  return readCredentials(env);
}

export function platformFetch(projectDir, options) {
  const inner = options.fetchFn ?? fetch;
  return isSandboxProject(projectDir) ? sandboxFetch(projectDir, inner) : inner;
}

export function sandboxStatePath(projectDir) {
  return join(projectDir, STATE_DIR, SANDBOX_STATE);
}

export function loadSandbox(projectDir) {
  try {
    const parsed = JSON.parse(readFileSync(sandboxStatePath(projectDir), 'utf-8'));
    return { version: 1, apps: [], keys: [], env: {}, deployments: {}, ...parsed };
  } catch {
    return { version: 1, apps: [], keys: [], env: {}, deployments: {} };
  }
}

export function saveSandbox(projectDir, state) {
  mkdirSync(join(projectDir, STATE_DIR), { recursive: true });
  writeFileSync(sandboxStatePath(projectDir), `${JSON.stringify(state, null, 2)}\n`);
}

export function sandboxResponse(status, data) {
  return { status, ok: status >= 200 && status < 300, json: async () => data, text: async () => JSON.stringify(data) };
}

// sandboxFetch — answers the platform routes the CLI uses; everything else is
// passed to `inner` (the real network, or a test stub).
export function sandboxFetch(projectDir, inner = fetch) {
  return async (url, init = {}) => {
    let parsed;
    try {
      parsed = new URL(String(url));
    } catch {
      return netFetch(inner, url, init);
    }
    const path = parsed.pathname;
    const method = String(init.method || 'GET').toUpperCase();
    const isPlatform = /\/v1\/(tenants|deployments|portal)(\/|$)/.test(path);
    if (!isPlatform) return netFetch(inner, url, init);

    const state = loadSandbox(projectDir);
    const json = () => {
      try {
        return typeof init.body === 'string' ? JSON.parse(init.body) : {};
      } catch {
        return {};
      }
    };
    const appBy = (appId, slug) =>
      state.apps.find((a) => (appId && a.id === appId) || (slug && a.slug === slug));
    const envKeys = (app) => Object.keys(state.env[app.id] || {}).sort();
    const reply = (status, data) => {
      saveSandbox(projectDir, state);
      return sandboxResponse(status, data);
    };

    let m;
    // --- control plane -------------------------------------------------------
    if ((m = /\/v1\/tenants\/[^/]+\/partitions$/.exec(path)) && method === 'POST') {
      const name = String(json().name || '').trim() || 'app';
      const slug = slugifyAppName(name);
      if (appBy(null, slug)) return reply(409, { error: `an app named "${name}" already exists` });
      const app = { id: randomUUID(), tenantId: 'sandbox', name, slug, createdAt: new Date().toISOString() };
      state.apps.push(app);
      return reply(201, app);
    }
    if (/\/v1\/tenants\/[^/]+\/(my-apps|partitions)$/.test(path) && method === 'GET') {
      return reply(200, { data: state.apps });
    }
    if (/\/v1\/tenants\/[^/]+\/api-keys$/.test(path) && method === 'POST') {
      const body = json();
      if (!appBy(body.partitionId, null)) return reply(404, { error: 'unknown app' });
      const key = `sk_test_sandbox_${randomBytes(16).toString('hex')}`;
      state.keys.push({ id: randomUUID(), appId: body.partitionId, prefix: key.slice(0, 20), createdAt: new Date().toISOString() });
      return reply(201, { key, environment: 'test' });
    }
    if (path.includes('/v1/portal/')) {
      return reply(400, { error: 'sandbox: sign-in is simulated; nothing to do here' });
    }

    // --- apps server -----------------------------------------------------------
    if (/\/v1\/deployments$/.test(path) && method === 'GET') {
      return reply(200, { data: Object.values(state.deployments), limits: { used: Object.keys(state.deployments).length, maxApps: 0 } });
    }
    if (/\/v1\/deployments$/.test(path) && method === 'POST') {
      const form = init.body;
      const field = (k) => (form && typeof form.get === 'function' ? form.get(k) : undefined);
      const app = appBy(field('appId'), slugifyAppName(String(field('app') || '')));
      if (!app) return reply(404, { error: 'unknown app — run init again' });
      const sent = (() => {
        try { return JSON.parse(field('env') || '{}'); } catch { return {}; }
      })();
      state.env[app.id] = { ...(state.env[app.id] || {}), ...sent };
      const required = (() => {
        try { return JSON.parse(field('requiredEnv') || '[]'); } catch { return []; }
      })();
      const missing = required.filter((k) => !(k in state.env[app.id]));
      if (missing.length) return reply(422, { error: `required settings not set: ${missing.join(', ')}` });
      const artifact = field('artifact');
      const artifactBytes = artifact && typeof artifact.size === 'number' ? artifact.size : 0;
      if (!artifactBytes) return reply(400, { error: 'empty artifact' });
      // Simulates the hosting check's confirm mode the way the server does it:
      // unpack the uploaded artifact and scan it.
      const findings = await (async () => {
        const unpack = mkdtempSync(join(tmpdir(), 'piezas-sandbox-artifact-'));
        try {
          const tgz = join(unpack, 'artifact.tar.gz');
          writeFileSync(tgz, Buffer.from(await artifact.arrayBuffer()));
          mkdirSync(join(unpack, 'app'));
          execSync(`tar -xzf ${JSON.stringify(tgz)} -C ${JSON.stringify(join(unpack, 'app'))}`);
          return scanArtifactHardNo(join(unpack, 'app'), String(field('kind') || 'server'));
        } catch {
          return [];
        } finally {
          rmSync(unpack, { recursive: true, force: true });
        }
      })();
      let riskAcknowledged = null;
      if (findings.length) {
        const fp = hardNoFingerprint(findings);
        if (String(field('acknowledgeHardNo') || '') !== fp) {
          const what = findings
            .map((f) => (f.rule === 'local-database'
              ? `the app keeps its own local database (${f.path})`
              : signInLeak(f)
                ? `a sign-in secret would be visible to everyone who opens the app (${f.path})`
                : `the Piezas key would be visible to everyone who opens the app (${f.path})`))
            .join('; ');
          return reply(409, {
            error: `Paused before going live: ${what}. Your AI tool can usually fix this. To deploy this version anyway, the app owner must confirm.`,
            needsConfirmation: true,
            fingerprint: fp,
            hardNo: findings,
          });
        }
        riskAcknowledged = { fingerprint: fp, findings, by: 'sandbox-owner', at: new Date().toISOString() };
      }
      const attestation = (() => {
        try { return JSON.parse(field('attestation') || 'null'); } catch { return null; }
      })();
      const dep = {
        slug: app.slug,
        appId: app.id,
        url: `https://${app.slug}.apps.piezas.ai`,
        status: 'running',
        kind: field('kind') || 'server',
        artifactBytes,
        attestation,
        deployedAt: new Date().toISOString(),
        simulated: true,
        ...(riskAcknowledged ? { riskAcknowledged } : {}),
        ...(field('testGateAcknowledged') ? { testGateAcknowledged: field('testGateAcknowledged') } : {}),
      };
      state.deployments[app.slug] = dep;
      return reply(201, { slug: dep.slug, url: dep.url, status: dep.status, kind: dep.kind, simulated: true });
    }
    if ((m = /\/v1\/deployments\/([^/]+)\/logs$/.exec(path)) && method === 'GET') {
      const dep = state.deployments[m[1]];
      if (!dep) return reply(404, { error: 'no deployment' });
      return reply(200, { logs: `[sandbox] ${dep.slug} was deployed (simulated) at ${dep.deployedAt}. No server runs in the sandbox, so there is no live output.` });
    }
    if ((m = /\/v1\/deployments\/([^/]+)\/env$/.exec(path)) && method === 'PATCH') {
      const app = appBy(parsed.searchParams.get('appId'), m[1]);
      if (!app) return reply(404, { error: 'unknown app' });
      const body = json();
      const cur = { ...(state.env[app.id] || {}), ...(body.set || {}) };
      for (const k of body.unset || []) delete cur[k];
      state.env[app.id] = cur;
      return reply(200, { slug: app.slug, status: state.deployments[app.slug] ? 'running' : 'not deployed', envKeys: envKeys(app) });
    }
    if ((m = /\/v1\/deployments\/([^/]+)$/.exec(path))) {
      const app = appBy(parsed.searchParams.get('appId'), m[1]);
      if (!app) return reply(404, { error: 'no such app' });
      const dep = state.deployments[app.slug];
      if (method === 'DELETE') {
        if (!dep) return reply(404, { error: 'no deployment' });
        delete state.deployments[app.slug];
        return reply(200, { slug: app.slug, deleted: true });
      }
      return reply(200, {
        slug: app.slug,
        url: dep?.url ?? null,
        status: dep ? dep.status : 'not deployed',
        envKeys: envKeys(app),
        simulated: true,
      });
    }
    return reply(404, { error: `sandbox: no simulated route for ${method} ${path}` });
  };
}

// signInContext tells the AI, at session start, whether this computer is
// signed in to the Piezas this setup uses, and what to do when it is not:
// sign in FIRST (the AI runs login; the person only clicks Approve), and never
// carry on with a real Piezas step without an account.
export function signInContext(env = process.env, cliPath) {
  const status = signInStatus(env);
  const cmd = cliPath ? `node "${cliPath}"` : 'npx piezas';
  if (status.signedIn) {
    return `Signed in to Piezas as ${status.email ?? 'unknown'}${status.tenantName ? ` (${status.tenantName})` : ''}.`;
  }
  const flag = savedTarget(env) === 'staging' ? ' --staging' : '';
  return [
    `Not signed in to Piezas${status.otherPiezas ? ` here (the saved sign-in is for ${status.otherPiezas}, not ${status.target})` : ''}.`,
    `Before any Piezas step (creating the app, settings, deploy), sign them in: run \`${cmd} login --start${flag}\` (it needs network access; ask for it up front),`,
    'then immediately post its link in the chat as a clickable Markdown link with the code: "Open this link to sign in: [Sign in to Piezas](<link>). Check the code says <code>, then click Approve."',
    `Then run \`${cmd} login --wait\` with a long timeout and do not continue until it reports success; if the code expires, start again.`,
    'Never carry on with a real Piezas step without an account.',
    'Only if the person explicitly asks to try without an account, use practice mode (init --sandbox) and say plainly that nothing real is created.',
  ].join(' ');
}

// connect — the socket the sign-in piece plugs into. Today it only explains.
export function connectApp(startDir = process.cwd()) {
  const sandbox = isSandboxProject(startDir);
  return {
    exitCode: SANDBOX_CONNECT_EXIT,
    command: 'connect',
    json: { command: 'connect', ok: false, status: 'not-available-yet', sandbox },
    output: [
      sandbox ? SANDBOX_NOTE : 'Connecting a project to Piezas from a coding tool arrives with Piezas sign-in.',
      'Until then, an existing account can still use `npx piezas login` and `npx piezas init`.',
    ],
  };
}

// ===========================================================================
// Deploying despite a never-rule finding: the OWNER confirms, not the AI
// ===========================================================================
//
// The hosting server pauses a deploy whose build breaks a never-rule and
// returns a fingerprint of exactly what it found. The owner confirms that
// fingerprint — at the terminal prompt, or by typing "deploy anyway" in their
// AI tool (recorded by the UserPromptSubmit hook into the guarded state file,
// so the AI cannot confirm for them). The next deploy sends it back; anything
// new asks again. During the BUILD the rules are never optional: the guards
// and the step gate still refuse.

export { DEPLOY_ANYWAY, DEPLOY_RISK_FILE, OWNER_APPROVALS_FILE };

export function pendingDeployRisk(projectDir) {
  const root = deployRecordRoot(projectDir);
  try {
    return JSON.parse(readFileSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), 'utf-8'));
  } catch {
    return null;
  }
}

export function clearPendingDeployRisk(projectDir) {
  const root = deployRecordRoot(projectDir);
  try {
    rmSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), { force: true });
  } catch {
    // best effort
  }
}

// deployRecordRoot — the app folder a deploy pause and its answer belong to:
// the protocol project, else the nearest folder with piezas.manifest.json or a
// waiting pause, else the folder itself.
export function deployRecordRoot(projectDir) {
  const protocolRoot = findProjectRoot(projectDir);
  if (protocolRoot) return protocolRoot;
  let d = resolve(projectDir);
  for (;;) {
    if (existsSync(join(d, 'piezas.manifest.json')) || existsSync(join(d, STATE_DIR, DEPLOY_RISK_FILE))) return d;
    const parent = dirname(d);
    if (parent === d) return resolve(projectDir);
    d = parent;
  }
}

// The owner's deploy decisions. A protocol project keeps them in its state
// file; an app without one in .piezas/owner-approvals.json. Both are written
// only by Piezas, from the owner's own reply (the workspace guard closes them
// to the AI).
function readOwnerApprovals(root) {
  try {
    const data = JSON.parse(readFileSync(join(root, STATE_DIR, OWNER_APPROVALS_FILE), 'utf-8'));
    return Array.isArray(data?.approvals) ? data.approvals.filter((a) => a && typeof a === 'object') : [];
  } catch {
    return [];
  }
}

export function deployApprovals(projectDir) {
  const root = deployRecordRoot(projectDir);
  let fromState = [];
  if (findProjectRoot(projectDir)) {
    try { fromState = loadState(root).approvals; } catch { fromState = []; }
  }
  return [...fromState, ...readOwnerApprovals(root)].filter((a) => a.gate === 'deploy-risk');
}

// A pause-wide record written alongside per-item answers (withItems) is kept
// for older readers only: here the per-item answers decide, so a change to an
// item (its words, its result) is asked again (Spec 1-D).
export function deployRiskApproved(projectDir, fingerprint) {
  if (!fingerprint) return false;
  return deployApprovals(projectDir).some((a) => a.fingerprint === fingerprint && !a.withItems);
}

// ownerChosePause — the owner once chose "deploy anyway" for this kind of
// pause (for example report-button-missing).
export function ownerChosePause(projectDir, pause) {
  return deployApprovals(projectDir).some((a) => a.pause === pause);
}

export function recordDeployRisk(projectDir, fingerprint, via, pause, { withItems = false } = {}) {
  if (!fingerprint) return false;
  const entry = { gate: 'deploy-risk', by: 'user', via, fingerprint, ...(pause ? { pause: String(pause) } : {}), ...(withItems ? { withItems: true } : {}), at: new Date().toISOString() };
  appendOwnerRecord(projectDir, entry, (a) => a.gate === 'deploy-risk' && a.fingerprint === fingerprint);
  return true;
}

// ---------------------------------------------------------------------------
// Answers per item (Spec 1-D). "deploy anyway" for a pause is kept for each
// thing it covered (a part of the app, a setting, a broken rule, the toolkit
// copy, the Report a problem button), keyed on that thing's own fingerprint:
// the next deploy asks only about what is new or changed. The pause's own
// fingerprint record (deploy-risk) is still written alongside, so older
// readers keep working.
// ---------------------------------------------------------------------------
export const DEPLOY_ITEM_GATE = 'deploy-item';

const itemId = (item) => `${item.kind}\u0000${item.key}\u0000${item.fp}`;

// An answer holds only until the thing it was about is fixed: a part that
// passes, a setting the live app now has. Then a clear record (written by
// Piezas, not the owner) ends every earlier answer for it; if it breaks again
// later, the owner is asked again.
export const DEPLOY_ITEM_CLEAR = 'deploy-item-clear';
const itemKeyPrefix = (kind, key) => `${kind}\u0000${key}\u0000`;

// An answer given to a pause shown for code that has changed since is bound
// to that code (`source`). Next to it goes the test record's code fingerprint
// when the pause was SHOWN (`recordCode`, kept on the pending pause): the
// Piezas MCP cannot see the code, only the test record the build carries, so
// it matches on that. Never the test record at answer time: the AI may have
// re-run the checks on newer code since the owner read the pause. Here the
// answer counts while either matches: `source` the code as it is now, or
// `recordCode` the test record as it is now.
export function testRecordCode(projectDir) {
  try {
    const fp = readTestAttestation(projectDir)?.sourceFingerprint;
    return typeof fp === 'string' && fp ? fp : null;
  } catch {
    return null;
  }
}

function liveItemAnswers(projectDir, { stale = null } = {}) {
  const map = new Map();
  let current;
  let recordNow;
  const sourceNow = () => (current ??= currentSource(projectDir));
  const recordCodeNow = () => (recordNow === undefined ? (recordNow = testRecordCode(projectDir)) : recordNow);
  const sameCode = (r) => r.source === sourceNow() || (typeof r.recordCode === 'string' && r.recordCode === recordCodeNow());
  for (const r of ownerRecords(projectDir)) {
    if (typeof r.kind !== 'string' || typeof r.key !== 'string') continue;
    if (r.gate === DEPLOY_ITEM_GATE && typeof r.fp === 'string') {
      if (typeof r.source === 'string' && !sameCode(r)) {
        stale?.set(itemKeyPrefix(r.kind, r.key), r);
        continue;
      }
      map.set(itemId(r), r);
    }
    else if (r.gate === DEPLOY_ITEM_CLEAR) {
      const prefix = itemKeyPrefix(r.kind, r.key);
      for (const id of [...map.keys()]) if (id.startsWith(prefix)) map.delete(id);
    }
  }
  return map;
}

// deployItemLookup — one read of the records; returns (item) => the latest
// matching answer still in force, or null.
export function deployItemLookup(projectDir) {
  const map = liveItemAnswers(projectDir);
  return (item) => map.get(itemId(item)) ?? null;
}

// deployItemRecords — what the build carries of the owner's per-item answers:
// those in force and every clear (Piezas' own "this is fixed now"), so a
// reader that cannot write them (the MCP) sees the same state.
export function deployItemRecords(projectDir) {
  const records = ownerRecords(projectDir);
  return {
    answers: [...liveItemAnswers(projectDir).values()],
    clears: records.filter((r) => r.gate === DEPLOY_ITEM_CLEAR),
  };
}

// liveItemKeys — the keys of this kind with an answer still in force.
export function liveItemKeys(projectDir, kind) {
  const keys = new Set();
  for (const r of liveItemAnswers(projectDir).values()) if (r.kind === kind) keys.add(r.key);
  return [...keys];
}

// earlierVersionAnswers — (item) => the owner's answer for this thing given
// to a pause about an earlier version of the code (it does not count for
// this one), or null.
export function earlierVersionAnswers(projectDir) {
  const stale = new Map();
  liveItemAnswers(projectDir, { stale });
  return (item) => stale.get(itemKeyPrefix(item.kind, item.key)) ?? null;
}

// clearDeployItems — these things are fixed now: end the owner's earlier
// answers for them (only where one is still in force).
export function clearDeployItems(projectDir, kind, keys, why) {
  const live = [...liveItemAnswers(projectDir).keys()];
  const at = new Date().toISOString();
  let cleared = 0;
  for (const key of new Set(keys ?? [])) {
    if (typeof key !== 'string' || !live.some((id) => id.startsWith(itemKeyPrefix(kind, key)))) continue;
    appendOwnerRecord(projectDir, { gate: DEPLOY_ITEM_CLEAR, by: 'piezas', kind, key, ...(why ? { why } : {}), at });
    cleared += 1;
  }
  return cleared;
}

export function recordDeployItems(projectDir, items, via, said, { source = null, unseen = false, recordCode = null } = {}) {
  const at = new Date().toISOString();
  for (const item of items ?? []) {
    if (!item || typeof item.kind !== 'string' || typeof item.key !== 'string' || typeof item.fp !== 'string') continue;
    appendOwnerRecord(projectDir, {
      gate: DEPLOY_ITEM_GATE, by: 'user', via, kind: item.kind, key: item.key, fp: item.fp,
      ...(item.title ? { title: String(item.title).slice(0, 200) } : {}),
      ...(said ? { said: String(said).slice(0, 200) } : {}),
      ...(typeof item.code === 'string' ? { code: item.code } : {}),
      ...(source ? { source } : {}),
      ...(source && recordCode ? { recordCode } : {}),
      ...(unseen ? { unseen: true } : {}),
      at,
    }, (a) => a.gate === DEPLOY_ITEM_GATE && itemId(a) === itemId(item) && (a.source ?? null) === (source ?? null) && !a.unseen === !unseen);
  }
}

// recordPauseAnswer — the owner's own "deploy anyway" for a waiting pause:
// its fingerprint, each older-style fingerprint it stands for, and every item.
// With items (decide), the per-item answers are what this CLI reads; the
// pause-wide records are marked withItems and kept for older readers only.
//
// The answer is about what the owner was shown. When the code changed after
// the pause was shown (pending.sourceFingerprint), each item is recorded for
// that earlier code only (`source`): the new version gets its own pause.
// `unseen`: nothing was shown (the AI was still working); such an answer is
// never called "the same as last time".
// Returns { recorded, changedSince }.
export function recordPauseAnswer(projectDir, pending, via, said, { unseen = false } = {}) {
  if (!pending?.fingerprint) return { recorded: false, changedSince: false };
  const source = pending.sourceFingerprint && pending.sourceFingerprint !== currentSource(projectDir) ? pending.sourceFingerprint : null;
  const withItems = Array.isArray(pending.decide) && pending.decide.length > 0;
  recordDeployRisk(projectDir, pending.fingerprint, via, pending.pause, { withItems });
  for (const l of Array.isArray(pending.legacy) ? pending.legacy : []) {
    if (l?.fingerprint && l.fingerprint !== pending.fingerprint) recordDeployRisk(projectDir, l.fingerprint, via, l.pause, { withItems });
  }
  // The test record's code when the pause was shown (never now).
  const recordCode = source && typeof pending.recordCode === 'string' && pending.recordCode ? pending.recordCode : null;
  if (withItems) recordDeployItems(projectDir, pending.decide, via, said, { source, unseen, recordCode });
  return { recorded: true, changedSince: Boolean(source) };
}

// writeShownPause — keep the pause a deploy just showed, for the owner's
// reply. It carries the test record's code as it is now (`recordCode`: what
// the pause was shown for). A shown pause the owner has not answered is never
// replaced: the new one waits (`next`) until the Stop hook sees the AI relay
// it in the chat (markPauseRelayed); until then the owner's reply is about
// the pause they read. Returns 'written' or 'queued'.
export function writeShownPause(projectDir, pending) {
  const root = deployRecordRoot(projectDir);
  const file = join(root, STATE_DIR, DEPLOY_RISK_FILE);
  const recordCode = testRecordCode(projectDir);
  const fresh = { ...pending, ...(recordCode ? { recordCode } : {}) };
  let shown = null;
  try { shown = JSON.parse(readFileSync(file, 'utf-8')); } catch { /* none */ }
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  if (shown?.fingerprint && !shown.silent && !shown.answered && shown.fingerprint !== fresh.fingerprint) {
    writeFileSync(file, `${JSON.stringify({ ...shown, next: fresh }, null, 2)}\n`);
    return 'queued';
  }
  writeFileSync(file, `${JSON.stringify(fresh, null, 2)}\n`);
  return 'written';
}

// relaysPause — the AI's message carries every line of the pause, word for
// word (spacing, quotes, bullets and punctuation aside).
const relayWords = (s) => String(s || '').toLowerCase().replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/[^a-z0-9']+/g, ' ').trim();
export function relaysPause(text, message) {
  const said = ` ${relayWords(text)} `;
  const lines = String(message || '').split('\n').map(relayWords).filter(Boolean);
  return lines.length > 0 && lines.every((l) => said.includes(` ${l} `));
}

// markPauseRelayed — the Stop half: the AI's final message relayed the
// waiting newer pause, so the owner has now read it: it takes the place of
// the one they read before.
export function markPauseRelayed(projectDir, payload) {
  const root = deployRecordRoot(projectDir);
  const file = join(root, STATE_DIR, DEPLOY_RISK_FILE);
  let shown = null;
  try { shown = JSON.parse(readFileSync(file, 'utf-8')); } catch { return false; }
  if (!shown?.next?.fingerprint || !relaysPause(lastAssistantText(payload), shown.next.message)) return false;
  writeFileSync(file, `${JSON.stringify({ ...shown.next, relayedAt: new Date().toISOString() }, null, 2)}\n`);
  return true;
}

// promoteQueuedPause — with no Stop hook to see the AI relay a newer pause
// (markPauseRelayed), the newest pause the deploy printed is the one the owner
// read: it takes the place of the older one before their relayed answer is
// recorded.
export function promoteQueuedPause(projectDir) {
  const root = deployRecordRoot(projectDir);
  const file = join(root, STATE_DIR, DEPLOY_RISK_FILE);
  let shown = null;
  try { shown = JSON.parse(readFileSync(file, 'utf-8')); } catch { return false; }
  if (!shown?.next?.fingerprint) return false;
  writeFileSync(file, `${JSON.stringify({ ...shown.next, needsShow: true }, null, 2)}\n`);
  return true;
}

// The line under a deploy pause when no hooks run in the session: the AI
// relays the owner's answer.
export const DEPLOY_RELAY_NOTE =
  'No Piezas hooks are installed for this project, so the owner\'s reply in the chat is not recorded on its own. ' +
  'After they answer, run: npx piezas deploy --owner-reply "<their exact words>" (only their own words count; never answer for them).';

// markPauseAnswered — the owner answered the waiting pause: the AI's next
// turn may take its place (writeSilentTestGate).
export function markPauseAnswered(projectDir) {
  const root = deployRecordRoot(projectDir);
  const file = join(root, STATE_DIR, DEPLOY_RISK_FILE);
  try {
    const pending = JSON.parse(readFileSync(file, 'utf-8'));
    if (pending && typeof pending === 'object') writeFileSync(file, `${JSON.stringify({ ...pending, answered: new Date().toISOString() }, null, 2)}\n`);
  } catch { /* nothing waiting */ }
}

// --- "this project deployed this app" ----------------------------------------

// The project's own deploy token (never leaves the machine; its hash does).
export function readDeployLink(projectDir) {
  try {
    const data = JSON.parse(readFileSync(join(deployRecordRoot(projectDir), STATE_DIR, DEPLOY_LINK_FILE), 'utf-8'));
    return data && typeof data.appId === 'string' && typeof data.token === 'string' ? data : null;
  } catch {
    return null;
  }
}

export const projectLinkHash = (token) => createHash('sha256').update(`piezas-project-link\u0000${token}`).digest('hex').slice(0, 32);

// deployLinkFor — the hash this project sends with a deploy of this app; the
// token is made once per app, on the first deploy from this project.
export function deployLinkFor(projectDir, appId) {
  let link = readDeployLink(projectDir);
  if (!link || link.appId !== appId) {
    link = { appId, token: randomBytes(24).toString('hex'), at: new Date().toISOString() };
    const root = deployRecordRoot(projectDir);
    mkdirSync(join(root, STATE_DIR), { recursive: true });
    writeFileSync(join(root, STATE_DIR, DEPLOY_LINK_FILE), `${JSON.stringify(link, null, 2)}\n`);
  }
  return projectLinkHash(link.token);
}

// deployedHereByHosting — what hosting's own record says: true (this project
// put the live version there), false (another one did), null (hosting keeps
// no such record for it: the caller falls back to the manifest).
export function deployedHereByHosting(projectDir, appId, deployment) {
  const remote = typeof deployment?.projectLink === 'string' && deployment.projectLink.trim() ? deployment.projectLink.trim() : null;
  if (!remote) return null;
  const local = readDeployLink(projectDir);
  return Boolean(local && local.appId === appId && projectLinkHash(local.token) === remote);
}

// The owner's own "link to <app name>", for an app this project did not put
// live (recorded by the hooks from their typed message, like "deploy anyway").
const linkName = (s) => String(s || '').toLowerCase().replace(/[‘’“”"'`]/g, '').replace(/\s+/g, ' ').trim();
export function ownerChoseLink(projectDir, appId) {
  return ownerRecords(projectDir, APP_LINK_GATE).some((r) => r.by === 'user' && r.appId === appId);
}

export function writeLinkQuestion(projectDir, app) {
  try {
    const root = deployRecordRoot(projectDir);
    mkdirSync(join(root, STATE_DIR), { recursive: true });
    writeFileSync(join(root, STATE_DIR, LINK_CONFIRM_FILE), `${JSON.stringify({ appId: app.id, appName: app.name, at: new Date().toISOString() }, null, 2)}\n`);
  } catch { /* the terminal path still works */ }
}

// recordAppLinkReply — the UserPromptSubmit half: the owner typed "link to
// <app name>" for the app the deploy asked about. Returns a note, or ''.
export function recordAppLinkReply(projectDir, prompt, via = 'user-prompt') {
  const said = linkName(prompt).replace(/[.!]+$/, '');
  const m = /^(?:please )?link (?:this project |it )?to (.+)$/.exec(said);
  if (!m) return '';
  const root = deployRecordRoot(projectDir);
  const file = join(root, STATE_DIR, LINK_CONFIRM_FILE);
  let pending = null;
  try { pending = JSON.parse(readFileSync(file, 'utf-8')); } catch { /* none */ }
  if (!pending?.appId || !pending.appName) return 'The owner asked to link this project to an app, but no deploy asked about one. Tell them where things stand in one sentence.';
  if (linkName(m[1]) !== linkName(pending.appName)) {
    return `The owner's words name "${m[1]}", not "${pending.appName}", so nothing was linked. Ask them to reply "link to ${pending.appName}" if that is the app they mean.`;
  }
  appendOwnerRecord(projectDir, { gate: APP_LINK_GATE, by: 'user', via, appId: pending.appId, appName: pending.appName, said: String(prompt).slice(0, 200), at: new Date().toISOString() });
  try { rmSync(file, { force: true }); } catch { /* best effort */ }
  return `The owner chose to link this project to "${pending.appName}"${via === 'relayed' ? '' : ' (they typed it themselves)'}, and it is recorded. Run the deploy again now; tell them in one sentence that its next version replaces the live one.`;
}

// ownerRecords — every owner decision kept for this app, oldest first: the
// protocol state's approvals and .piezas/owner-approvals.json. Optionally only
// one gate's entries.
export function ownerRecords(projectDir, gate) {
  const root = deployRecordRoot(projectDir);
  let fromState = [];
  if (findProjectRoot(projectDir)) {
    try { fromState = loadState(root).approvals; } catch { fromState = []; }
  }
  const all = orderOwnerRecords(fromState, readOwnerApprovals(root));
  return gate ? all.filter((a) => a.gate === gate) : all;
}

// orderOwnerRecords — the rule shared with the Piezas MCP server, exactly:
// take both files' entries (state.json's approvals, then owner-approvals.json);
// drop any whose `at` parses to more than now + 5 minutes; stable-sort by the
// parsed `at`, ascending; entries whose `at` does not parse keep their source
// order and sort before every dated entry (state.json's before
// owner-approvals.json's, then each file's own order, on equal keys). The last
// entry wins.
export function orderOwnerRecords(fromState, fromFile, now = Date.now()) {
  const tagged = [...fromState, ...fromFile].map((entry, index) => ({ entry, index, at: Date.parse(entry?.at) }));
  return tagged
    .filter((t) => !Number.isFinite(t.at) || t.at <= now + 5 * 60 * 1000)
    .sort((a, b) => {
      const da = Number.isFinite(a.at);
      const db = Number.isFinite(b.at);
      if (da !== db) return da ? 1 : -1;
      if (da && a.at !== b.at) return a.at - b.at;
      return a.index - b.index;
    })
    .map((t) => t.entry);
}

// appendOwnerRecord — keep one owner decision where this app keeps them (the
// protocol state, else .piezas/owner-approvals.json). Called only from the
// owner's own reply or terminal answer, never from anything the AI writes.
// `same` (optional) finds an equal entry already kept: then nothing is added.
export function appendOwnerRecord(projectDir, entry, same) {
  const protocolRoot = findProjectRoot(projectDir);
  if (protocolRoot) {
    const state = loadState(protocolRoot);
    if (same && state.approvals.some(same)) return false;
    saveState(protocolRoot, { ...state, approvals: [...state.approvals, entry] });
    return true;
  }
  const root = deployRecordRoot(projectDir);
  const approvals = readOwnerApprovals(root);
  if (same && approvals.some(same)) return false;
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  writeFileSync(join(root, STATE_DIR, OWNER_APPROVALS_FILE), `${JSON.stringify({ version: 1, approvals: [...approvals, entry] }, null, 2)}\n`);
  return true;
}

// confirmedDeployRisk — the pending fingerprint, if the owner has confirmed it.
export function confirmedDeployRisk(projectDir) {
  const pending = pendingDeployRisk(projectDir);
  if (!pending?.fingerprint) return null;
  return deployRiskApproved(projectDir, pending.fingerprint) ? pending.fingerprint : null;
}

// scanArtifactHardNo — mirrors the hosting server's scan (App Hosting Backend,
// internal/appsd/hardno.go) on the staged artifact, in the same order, so both
// sides find the same things and compute the same fingerprint.
export const ARTIFACT_LOCAL_DB_PACKAGES = [
  'better-sqlite3', 'sqlite3', 'pg', 'mysql2', 'mongoose', 'knex', 'sequelize',
  'typeorm', 'drizzle-orm', 'prisma', '@prisma/client',
];
export const ARTIFACT_DB_EXTS = new Set(['.sqlite', '.sqlite3', '.db']);
export const ARTIFACT_SCAN_EXTS = new Set(['.js', '.mjs', '.cjs', '.html', '.json', '.py', '.txt', '.css']);
export const ARTIFACT_BROWSER_ROOTS = ['.next/static', 'public', 'static', 'dist/client', 'build/static'];
export const ARTIFACT_MAX_FILE = 4 << 20;
export const ARTIFACT_MAX_TOTAL = 64 << 20;

// Lexical, depth-first, like Go's filepath.WalkDir. visit returns 'stop' to end.
export function walkLexical(dir, visit) {
  let entries;
  try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return false; }
  entries.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  for (const e of entries) {
    const full = join(dir, e.name);
    if (e.isDirectory()) {
      if (e.name === 'node_modules') continue;
      if (walkLexical(full, visit)) return true;
    } else if (visit(full, e) === 'stop') {
      return true;
    }
  }
  return false;
}

// browserLeak — every leak in this text, one per distinct match: { category,
// detail, hash }. The detail is the kind of leak in plain words plus a short
// hash of what matched (`#1a2b3c4d5e6f`), never the matched text itself, so a
// different secret of the same kind is a different finding.
const leakHash = (token) => createHash('sha256').update(token).digest('hex').slice(0, 12);
const LEAK_KINDS = [
  ['piezas-key-value', /\bsk_(?:live|test)_[A-Za-z0-9]{12,}/g, () => 'contains a Piezas secret key value'],
  ['piezas-key-public-var', /\b(?:NEXT_PUBLIC|VITE|PUBLIC)_[A-Z0-9_]*PIEZAS_API_KEY\b/g, () => 'reads the Piezas API key through a public (browser) variable'],
  ['google-secret', /\bGOCSPX-[A-Za-z0-9_-]{20,}/g, () => 'contains a Google sign-in client secret'],
  ['microsoft-secret', /\b[A-Za-z0-9_.-]{3}\dQ~[A-Za-z0-9_.~-]{31,34}/g, () => 'contains a Microsoft sign-in client secret'],
  ['sign-in-public-var', /\b(?:NEXT_PUBLIC|VITE|PUBLIC)_[A-Z0-9_]*(?:CLIENT_SECRET|SSO_SECRET)\b/g, (t) => `exposes ${t} to browsers`],
  ['piezas-public-var', /\b(?:NEXT_PUBLIC|VITE|PUBLIC)_PIEZAS_[A-Z0-9_]*(?:KEY|SECRET|TOKEN)\b/g, (t) => (t.includes('PUBLISHABLE') || /PIEZAS_API_KEY$/.test(t) ? null : `exposes ${t} to browsers`)],
];
export function browserLeak(text) {
  const out = [];
  for (const [category, re, say] of LEAK_KINDS) {
    const seen = new Set();
    for (const m of String(text).matchAll(re)) {
      if (seen.has(m[0])) continue;
      seen.add(m[0]);
      const words = say(m[0]);
      if (!words) continue;
      const hash = leakHash(m[0]);
      out.push({ category, detail: `${words} (#${hash})`, hash });
    }
  }
  return out;
}

// browserLeakFirst — what the hosting server's scan says of this text (its
// first kind of leak, in its words), for the mirror whose fingerprint is sent
// to the server; '' when none.
export function browserLeakFirst(text) {
  const first = browserLeak(text)[0];
  return first ? first.detail.replace(/ \(#[0-9a-f]+\)$/, '') : '';
}

// The most leak findings one deploy lists (the rest are counted).
export const ARTIFACT_MAX_LEAKS = 20;

// scanArtifactLeaksAll — every browser leak: one finding per distinct match,
// each with a short hash of what matched (so a different secret of the same
// kind in the same file is a different finding). Capped; `more` counts the
// rest, `beyond` holds them, and one more finding stands for them all, keyed
// on all their hashes, so a change past the cap is asked about too; `scanned`
// holds every file the scan read.
export function scanArtifactLeaksAll(root, kind, cap = ARTIFACT_MAX_LEAKS) {
  const findings = [];
  const beyond = [];
  let more = 0;
  const roots = kind === 'static' ? ['.'] : ARTIFACT_BROWSER_ROOTS;
  let scanned = 0;
  const seen = new Set();
  const read = new Set();
  for (const r of roots) {
    const base = join(root, r);
    if (!existsSync(base)) continue;
    walkLexical(base, (full) => {
      if (!ARTIFACT_SCAN_EXTS.has(extname(full).toLowerCase())) return undefined;
      const rel = toPosix(relative(root, full));
      if (seen.has(rel)) return undefined;
      seen.add(rel);
      let size;
      try { size = statSync(full).size; } catch { return undefined; }
      if (size > ARTIFACT_MAX_FILE) return undefined;
      scanned += size;
      if (scanned > ARTIFACT_MAX_TOTAL) return 'stop';
      let text;
      try { text = readFileSync(full, 'latin1'); } catch { return undefined; }
      read.add(rel);
      for (const leak of browserLeak(text)) {
        const finding = { rule: 'key-in-browser', path: rel, detail: leak.detail, category: leak.category, digest: leak.hash };
        if (findings.length >= cap) { more += 1; beyond.push(finding); continue; }
        findings.push(finding);
      }
      return undefined;
    });
  }
  if (beyond.length) {
    const digest = leakHash(beyond.map((f) => `${f.path}\u0000${f.digest}`).join('\n'));
    findings.push({ rule: 'key-in-browser', path: '', detail: `${more} more ${more === 1 ? 'leak' : 'leaks'} past the first ${cap} (#${digest})`, category: 'beyond-cap', digest });
  }
  return { findings, more, beyond, scanned: read };
}

// scanArtifactFindings — what the one pause asks about: the never-rules as the
// server mirror finds them (the local database), and every browser leak.
export function scanArtifactFindings(root, kind) {
  const mirror = scanArtifactHardNo(root, kind);
  const { findings: leaks, more, beyond, scanned } = scanArtifactLeaksAll(root, kind);
  return { findings: [...mirror.filter((f) => f.rule !== 'key-in-browser'), ...leaks], more, beyond, mirror, scanned };
}

export function scanArtifactHardNo(root, kind) {
  const out = [];
  for (const pkg of ARTIFACT_LOCAL_DB_PACKAGES) {
    const rel = `node_modules/${pkg}/package.json`;
    if (existsSync(join(root, rel))) {
      out.push({ rule: 'local-database', path: rel, detail: `bundles ${pkg}` });
      break;
    }
  }
  if (!out.length) {
    walkLexical(root, (full) => {
      if (ARTIFACT_DB_EXTS.has(extname(full).toLowerCase())) {
        out.push({ rule: 'local-database', path: toPosix(relative(root, full)), detail: 'ships a database file' });
        return 'stop';
      }
      return undefined;
    });
  }
  const roots = kind === 'static' ? ['.'] : ARTIFACT_BROWSER_ROOTS;
  let scanned = 0;
  for (const r of roots) {
    const base = join(root, r);
    if (!existsSync(base)) continue;
    let found = false;
    walkLexical(base, (full) => {
      if (!ARTIFACT_SCAN_EXTS.has(extname(full).toLowerCase())) return undefined;
      let size;
      try { size = statSync(full).size; } catch { return undefined; }
      if (size > ARTIFACT_MAX_FILE) return undefined;
      scanned += size;
      if (scanned > ARTIFACT_MAX_TOTAL) { found = true; return 'stop'; }
      let text;
      try { text = readFileSync(full, 'latin1'); } catch { return undefined; }
      const detail = browserLeakFirst(text);
      if (detail) {
        out.push({ rule: 'key-in-browser', path: toPosix(relative(root, full)), detail });
        found = true;
        return 'stop';
      }
      return undefined;
    });
    if (found) break;
  }
  return out;
}

// hardNoFingerprint — identical to the server's: sha256 of the sorted
// "rule\0path" lines, first 24 hex characters.
export function hardNoFingerprint(findings) {
  return createHash('sha256')
    .update(findings.map((f) => `${f.rule}\u0000${f.path}`).sort().join('\n'))
    .digest('hex')
    .slice(0, 24);
}

// hardNoOwnerWords — what each broken rule means for the owner, one sentence
// per kind (the one source for this wording). No file names for the owner:
// where it is goes to the AI.
export function hardNoOwnerWords(findings) {
  return [...new Set(findings.map((f) => (f.rule === 'local-database'
    ? 'The app keeps its own local database, so those records are not in Piezas.'
    : signInLeak(f)
      ? 'A sign-in secret would be visible to everyone who opens the app.'
      : 'The Piezas key would be visible to everyone who opens the app.')))];
}

export function hardNoConfirmMessage(findings) {
  const parts = hardNoOwnerWords(findings).map((w) => w.replace(/^./, (c) => c.toLowerCase()).replace(/\.$/, ''));
  return `Paused before going live: ${parts.join('; ')}. Your AI tool can usually fix this. To deploy this version anyway, the app owner must confirm.`;
}

// signInLeak — the leak is a Google/Microsoft sign-in secret, not the Piezas
// key: by its category, by hosting's rule, or (a finding with no category,
// as the artifact scan gives) by its detail. Wording only; keys never change.
const SIGN_IN_LEAKS = new Set(['google-secret', 'microsoft-secret', 'sign-in-public-var']);
function signInLeak(f) {
  if (typeof f?.category === 'string' && f.category) return SIGN_IN_LEAKS.has(f.category);
  if (f?.rule === 'signin-secret-in-browser') return true;
  return f?.rule === 'key-in-browser' && /sign-in client secret|_(?:CLIENT|SSO)_SECRET to browsers/.test(String(f.detail ?? ''));
}

// hardNoItems — the per-item answers for never-rule findings, the same on
// both sides (the deploy's own scan and the hosting server's), so one "deploy
// anyway" covers both. Keyed on the rule and where it is; the answer (fp) is
// for this exact finding, its detail included: a different leak in the same
// file is asked again. A finding with no path still gets an item.
export function hardNoItems(findings) {
  return (Array.isArray(findings) ? findings : []).filter((f) => f && f.rule).map((f) => {
    const path = typeof f.path === 'string' ? f.path : '';
    // A finding from the full local scan names its kind of leak (category)
    // and what matched (digest, also in its detail): each match is its own
    // item, and a different secret of the same kind is a different answer.
    const category = typeof f.category === 'string' && f.category ? f.category : null;
    const digest = typeof f.digest === 'string' && f.digest ? f.digest : null;
    return {
      kind: 'rule',
      key: `${f.rule}\u0000${path}${category ? `\u0000${category}${digest ? `\u0000${digest}` : ''}` : ''}`,
      fp: createHash('sha256').update(`${f.rule}\u0000${path}\u0000${typeof f.detail === 'string' ? f.detail : ''}${digest ? `\u0000${digest}` : ''}`).digest('hex').slice(0, 24),
      title: f.rule === 'local-database' ? 'its own local database' : signInLeak(f) ? 'a sign-in secret in the browser' : 'the Piezas key in the browser',
      finding: f,
    };
  });
}

// deployNeedsConfirmation — the hosting server found a broken rule this
// deploy's own scan did not: the same one pause (one message, one answer,
// remembered per item), never a second, older-style stop.
export async function deployNeedsConfirmation(projectDir, options, data) {
  const findings = Array.isArray(data.hardNo) ? data.hardNo : [];
  const decide = hardNoItems(findings).map(({ finding, ...item }) => item);
  const answered = deployItemLookup(projectDir);
  // Already answered for exactly these (the owner's own "deploy anyway"):
  // confirm to the server once, without asking again.
  if (decide.length && decide.every((i) => answered(i)) && options.acknowledge !== data.fingerprint) {
    return deploy({ ...options, acknowledge: data.fingerprint });
  }
  const lines = [
    PAUSE_TEXT.single,
    findings.length ? PAUSE_TEXT.rules(findings) : 'This version breaks a Piezas rule. Your AI tool can usually fix this.',
    OWNER_PAUSE_TEXT.nothingLive,
    OWNER_PAUSE_TEXT.choice,
  ];
  const pending = {
    kind: 'hard-no',
    pause: 'needs-confirmation',
    fingerprint: data.fingerprint,
    legacy: [{ fingerprint: data.fingerprint, pause: 'hard-no' }],
    decide,
    hardNo: findings,
    message: lines.join('\n'),
    at: new Date().toISOString(),
  };
  writeShownPause(projectDir, pending);
  log('');
  for (const line of lines) log(`  ${line}`);
  log('');

  const canAsk = !options.acknowledge && ownerAtTerminal(options);
  if (canAsk) {
    const promptFn = options.promptFn ?? promptViaTerminal;
    const answer = String((await promptFn(`  ${OWNER_PAUSE_TEXT.terminalPrompt}`)) ?? '').trim().toLowerCase().replace(/[.!]+$/, '');
    if (answer === DEPLOY_ANYWAY) {
      recordPauseAnswer(projectDir, pending, 'terminal', answer);
      log('');
      return deploy({ ...options, acknowledge: data.fingerprint });
    }
    log(`  ${OWNER_PAUSE_TEXT.stopped}\n`);
  } else {
    if (findings.length) log(`  (For the AI: where: ${findings.map((f) => `${f.path}${f.detail ? ` (${f.detail})` : ''}`).join('; ')}. Fix it, or the owner decides. Only the owner's own "${DEPLOY_ANYWAY}" counts; never type it or treat "go ahead" as it.)`);
    if (relayAllowed(deployRecordRoot(projectDir))) log(`  (For the AI: ${DEPLOY_RELAY_NOTE})`);
    log('');
  }
  return { exitCode: 1, command: 'deploy', status: 'needs-confirmation', ownerCanOverride: true, fingerprint: data.fingerprint, hardNo: findings };
}

// ===========================================================================
// Showcase: what the customer looks at instead of reading a requirements doc
// ===========================================================================
//
// .piezas/showcase/index.html — the app in plain words (overview + what it
// does, no ids), screenshots of the key screens (desktop + phone), and short
// clips of each journey recorded from the scenario tests. The customer approves
// what they SAW. Screens and clips use the Playwright the test harness installs.

export const SHOWCASE_DIR = 'showcase';

export function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

export function readSpecForShowcase(root) {
  let text = '';
  try {
    text = readFileSync(join(root, SPEC_FILE), 'utf-8');
  } catch {
    return { overview: '', requirements: [], scenarios: [] };
  }
  const lines = blankComments(text).split(/\r?\n/);
  const sections = splitSections(lines);
  // Provenance notes ("(Stated: …)", "(Assumed)", "(from x.xlsx)") are for the
  // builder; the customer only needs to know which lines were GUESSES.
  const PROVENANCE = /\s*\((?:stated|assumed|assumption|from|source)\b[^)]*\)/gi;
  const overview = (sections.get('overview')?.lines ?? [])
    .map((l) => l.text.trim())
    .filter((t) => t && !t.startsWith('#'))
    .join(' ')
    .replace(PROVENANCE, '')
    .trim();
  const requirements = (sections.get('requirements')?.lines ?? [])
    .map((l) => {
      const m = REQUIREMENT_LINE.exec(l.text);
      if (!m) return null;
      const raw = l.text.slice(m.index + m[0].length);
      const assumed = /\((?:[^)]*;\s*)?assum/i.test(raw);
      const text = raw.replace(PROVENANCE, '').replace(/\*\*/g, '').trim();
      return text ? { text, assumed } : null;
    })
    .filter(Boolean);
  const scenarios = parseSpec(text).scenarios.map((sc) => ({ id: sc.id, title: sc.title }));
  return { overview, requirements, scenarios };
}

export function showcasePath(root, ...parts) {
  return join(root, STATE_DIR, SHOWCASE_DIR, ...parts);
}

export function listDirSafe(dir) {
  try {
    return readdirSync(dir).sort();
  } catch {
    return [];
  }
}

export function buildShowcase(startDir = process.cwd(), options = {}) {
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  const appName = readManifestSafe(root)?.appName || basename(root);
  const spec = readSpecForShowcase(root);
  const stateFile = showcasePath(root, 'showcase.json');
  let saved = {};
  try {
    saved = JSON.parse(readFileSync(stateFile, 'utf-8'));
  } catch {
    // first build
  }
  const previewUrl = options.previewUrl || saved.previewUrl || '';
  // Journey-end screens (S-nnn.png: signed in, real state) lead; URL shots follow.
  const allShots = listDirSafe(showcasePath(root, 'shots')).filter((f) => f.endsWith('.png'));
  const shots = [...allShots.filter((f) => /^S-\d{3,}\.png$/.test(f)), ...allShots.filter((f) => !/^S-\d{3,}\.png$/.test(f))];
  const clips = listDirSafe(showcasePath(root, 'clips')).filter((f) => f.endsWith('.webm'));
  const titleFor = (id) => spec.scenarios.find((sc) => sc.id === id)?.title || 'Journey';
  const label = (file) => {
    const id = /^(S-\d{3,})\.png$/.exec(file)?.[1];
    if (id) return titleFor(id);
    return file.replace(/\.png$/, '').replace(/-(desktop|phone)$/, ' ($1)').replace(/-/g, ' ');
  };

  const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(appName)}</title>
<style>
:root{--bg:#faf9f6;--ink:#1c1b19;--muted:#5d5a54;--card:#fff;--line:#e5e1d8;--accent:#0e7c5a}
@media (prefers-color-scheme:dark){:root{--bg:#161512;--ink:#f1eee8;--muted:#b3ada3;--card:#211f1b;--line:#38342d;--accent:#5fc59e}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;padding:32px 20px 64px}
main{max-width:960px;margin:0 auto}h1{font-size:32px;margin:0 0 8px}h2{font-size:20px;margin:40px 0 12px}
.lede{color:var(--muted);font-size:18px;max-width:65ch}.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:18px 22px}
ul{margin:0;padding-left:20px}li{margin:6px 0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px}
figure{margin:0}img,video{width:100%;border:1px solid var(--line);border-radius:10px;background:#000}figcaption{color:var(--muted);font-size:14px;margin-top:6px}
a{color:var(--accent)}.empty{color:var(--muted)}.guess{display:inline-block;margin-left:6px;padding:1px 8px;border-radius:999px;font-size:12px;background:#fdf1d8;color:#7a5200}@media (prefers-color-scheme:dark){.guess{background:#4a3a14;color:#f3d48a}}
</style></head><body><main>
<h1>${escapeHtml(appName)}</h1>
${spec.overview ? `<p class="lede">${escapeHtml(spec.overview)}</p>` : ''}
${previewUrl ? `<p>Try it yourself: <a href="${escapeHtml(previewUrl)}">${escapeHtml(previewUrl)}</a> (sample data only)</p>` : ''}
<h2>What it does</h2>
<div class="card">${spec.requirements.length ? `<ul>${spec.requirements.map((r) => `<li>${escapeHtml(r.text)}${r.assumed ? ' <span class="guess">my guess — check this</span>' : ''}</li>`).join('')}</ul>` : '<p class="empty">The description is still being written.</p>'}</div>
<h2>The screens</h2>
${shots.length ? `<div class="grid">${shots.map((f) => `<figure><img src="shots/${escapeHtml(f)}" alt="${escapeHtml(label(f))}"><figcaption>${escapeHtml(label(f))}</figcaption></figure>`).join('')}</div>` : '<p class="empty">Screens appear here once the preview is running.</p>'}
<h2>Watch it work</h2>
${clips.length ? `<div class="grid">${clips.map((f) => `<figure><video src="clips/${escapeHtml(f)}" controls muted playsinline></video><figcaption>${escapeHtml(titleFor(f.replace(/\.webm$/, '')))}</figcaption></figure>`).join('')}</div>` : '<p class="empty">Short clips of each journey appear here once the app is built and tested.</p>'}
</main></body></html>
`;
  mkdirSync(showcasePath(root), { recursive: true });
  writeFileSync(showcasePath(root, 'index.html'), html);
  writeFileSync(stateFile, `${JSON.stringify({ previewUrl }, null, 2)}\n`);
  return { page: showcasePath(root, 'index.html'), shots: shots.length, clips: clips.length };
}

// collectClips — Playwright writes one folder per test with video.webm; keep
// one clip per scenario (the folder name carries the S-nnn of its file).
export function collectClips(startDir = process.cwd()) {
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  const raw = showcasePath(root, 'clips-raw');
  const out = showcasePath(root, 'clips');
  mkdirSync(out, { recursive: true });
  const found = [];
  for (const name of listDirSafe(raw)) {
    const id = /\b(S-\d{3,})\b/.exec(name)?.[1];
    const video = join(raw, name, 'video.webm');
    if (!id || !existsSync(video) || found.some((c) => c.scenario === id)) continue;
    copyFileSync(video, join(out, `${id}.webm`));
    // The screen at the END of the journey — signed in, real state — beats a
    // screenshot of a URL, which for most apps is the sign-in page.
    const still = listDirSafe(join(raw, name)).find((f) => /^test-finished.*\.png$/.test(f));
    if (still) {
      mkdirSync(showcasePath(root, 'shots'), { recursive: true });
      copyFileSync(join(raw, name, still), showcasePath(root, 'shots', `${id}.png`));
    }
    found.push({ scenario: id, file: `${id}.webm` });
  }
  return found.sort((a, b) => a.scenario.localeCompare(b.scenario));
}

export function hasPlaywright(root) {
  return existsSync(join(root, 'node_modules', '@playwright', 'test', 'package.json'));
}

export const PLAYWRIGHT_MISSING = 'screens and clips need the test tools installed once: npm install && npx playwright install';

export function routeSlug(route) {
  return route.replace(/^\/+|\/+$/g, '').replace(/[^a-zA-Z0-9]+/g, '-').toLowerCase() || 'home';
}

export async function previewShots(startDir = process.cwd(), options = {}) {
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  const url = typeof options.url === 'string' && options.url ? options.url.replace(/\/+$/, '') : '';
  const routes = Array.isArray(options.routes) && options.routes.length ? options.routes : ['/'];
  if (!url) return { exitCode: 2, command: 'preview shots', output: ['preview shots needs --url <the running preview, e.g. http://localhost:3000>'] };
  if (!hasPlaywright(root)) return { exitCode: 1, command: 'preview shots', output: [PLAYWRIGHT_MISSING] };

  const dir = showcasePath(root, 'shots');
  mkdirSync(dir, { recursive: true });
  const script = showcasePath(root, 'shots.mjs');
  writeFileSync(script, `import { chromium, devices } from '@playwright/test';
const [url, outDir, routes] = [process.argv[2], process.argv[3], JSON.parse(process.argv[4])];
const browser = await chromium.launch();
const sizes = { desktop: { viewport: { width: 1280, height: 800 } }, phone: devices['iPhone 13'] };
for (const [name, ctxOpts] of Object.entries(sizes)) {
  const context = await browser.newContext(ctxOpts);
  const page = await context.newPage();
  for (const { route, slug } of routes) {
    await page.goto(url + route, { waitUntil: 'networkidle' });
    await page.screenshot({ path: outDir + '/' + slug + '-' + name + '.png', fullPage: false });
  }
  await context.close();
}
await browser.close();
`);
  const runner = options.execFn ?? ((cmd, args, opts) => spawnSync(cmd, args, opts));
  const result = runner(process.execPath, [script, url, dir, JSON.stringify(routes.map((r) => ({ route: r.startsWith('/') ? r : `/${r}`, slug: routeSlug(r) })))], {
    cwd: root,
    encoding: 'utf-8',
  });
  if (result.status !== 0) {
    const detail = String(result.stderr || result.stdout || '').split('\n').find((l) => l.trim()) || 'unknown error';
    return { exitCode: 1, command: 'preview shots', output: [`could not capture the screens: ${detail.slice(0, 200)}`, `is the preview running at ${url}?`] };
  }
  const page = buildShowcase(root, { previewUrl: url });
  return { exitCode: 0, command: 'preview shots', page: page.page, output: [`screens: ${page.shots} captured`, `showcase: ${page.page}`] };
}

export async function previewClips(startDir = process.cwd(), options = {}) {
  const root = findProjectRoot(startDir) ?? resolve(startDir);
  if (!hasPlaywright(root)) return { exitCode: 1, command: 'preview clips', output: [PLAYWRIGHT_MISSING] };
  const configName = existsSync(join(root, 'playwright.config.ts')) ? 'playwright.config.ts' : 'playwright.config.js';
  mkdirSync(showcasePath(root), { recursive: true });
  rmSync(showcasePath(root, 'clips-raw'), { recursive: true, force: true });
  const wrapper = showcasePath(root, 'clips.config.ts');
  // A wrapper, so ANY project's config gets video without being edited.
  // Relative paths in the project's config (its webServer's cwd above all)
  // resolve against the CONFIG's folder, so point them back at the project.
  writeFileSync(wrapper, `import base from '../../${configName.replace(/\.(ts|js)$/, '')}';
const atRoot = (w) => ({ ...w, cwd: w.cwd ? '../../' + w.cwd : '../..' });
export default {
  ...base,
  testDir: '../../tests/scenarios',
  outputDir: './clips-raw',
  reporter: 'line',
  retries: 0,
  use: { ...(base.use ?? {}), video: 'on', screenshot: 'on' },
  webServer: Array.isArray(base.webServer) ? base.webServer.map(atRoot) : base.webServer ? atRoot(base.webServer) : undefined,
};
`);
  const env = { ...process.env, ...(options.url ? { PW_BASE_URL: options.url } : {}) };
  const runner = options.execFn ?? ((cmd, args, opts) => spawnSync(cmd, args, opts));
  runner('npx', ['playwright', 'test', '--config', wrapper], { cwd: root, env, encoding: 'utf-8' });
  const clips = collectClips(root);
  const page = buildShowcase(root, { previewUrl: options.url });
  return {
    exitCode: clips.length ? 0 : 1,
    command: 'preview clips',
    page: page.page,
    output: clips.length
      ? [`clips: ${clips.length} journeys recorded`, `showcase: ${page.page}`]
      : ['no clips were recorded — are there scenario tests in tests/scenarios, and is the app running?'],
  };
}

// ===========================================================================
// When hooks are off: notice it, and re-check at checkpoints
// ===========================================================================

export const GUARD_MARKER = 'guard.json';
export const GUARD_STALE_MS = 15 * 60 * 1000;

// hardNoFindings — the never-rules only, synchronously, from the SAME scanners
// doctor uses (one source of truth). Used where a hook may not have run:
// moving to the next step, deploying, and the end-of-turn check.
export function hardNoFindings(projectDir) {
  const dir = resolve(projectDir);
  const findings = [];
  const files = existsSync(dir) ? listFiles(dir) : [];
  scanSecretExposure(dir, files, findings);
  scanOAuthTokenStorage(dir, files, findings);
  scanLocalDatabaseUsage(dir, files, findings);
  scanPublicSecretNames(dir, files, findings);
  return findings.filter((f) => f.severity === 'error' && HARD_NO_CODES.has(f.code));
}

// hooksRunning — have this project's hooks run in the last GUARD_STALE_MS (the
// marker every hook event refreshes)? When they have not (the Claude connector,
// the Codex directory plugin, a project set up through the MCP, a session not
// trusted yet), nothing can record the owner's own reply in the chat, so the
// AI may relay their exact words (--owner-reply).
export function hooksRunning(root) {
  if (!root) return false;
  try {
    const marker = JSON.parse(readFileSync(join(root, STATE_DIR, GUARD_MARKER), 'utf-8'));
    const age = Date.now() - Date.parse(marker.lastSeen);
    return marker.active === true && Number.isFinite(age) && age >= 0 && age < GUARD_STALE_MS;
  } catch {
    return false;
  }
}

// relayAllowed — may the AI relay the owner's words (--owner-reply) to
// `piezas deploy` / `piezas test` here? Only in a project with no Piezas
// project hooks installed (.piezas/hooks/hook.mjs: the connector, the Codex
// directory plugin, a project set up through the MCP) and none seen running
// (the plugin's). Where the project hooks are installed, they record the
// owner's own reply; a session that has not trusted them yet is told how to
// (guardWarning). The hook files are closed to the AI, so this cannot be
// faked by deleting a marker.
export function relayAllowed(root) {
  if (!root) return false;
  if (existsSync(join(root, STATE_DIR, 'hooks', 'hook.mjs'))) return false;
  return !hooksRunning(root);
}

export function writeGuardMarker(root, payload) {
  try {
    mkdirSync(join(root, STATE_DIR), { recursive: true });
    const host = payload && typeof payload.turn_id === 'string' ? 'codex' : 'claude-code';
    writeFileSync(
      join(root, STATE_DIR, GUARD_MARKER),
      `${JSON.stringify({ active: true, host, lastSeen: new Date().toISOString() })}\n`,
    );
  } catch {
    // best effort: a marker we cannot write must never break a hook
  }
}

// How guardWarning says to switch the checks back on, for where the tool runs.
// A terminal (and any case that cannot be told) keeps the sentence from before,
// word for word; the apps get their own. When where the tool runs is not
// known, the app's step follows the terminal sentence.
export const GUARDS_ON_TEXT = {
  terminal: 'In Claude Code or Codex, turn them back on: keep the Piezas plugin enabled (Codex: open /hooks and trust Piezas). ',
  app: {
    codex: 'In the Codex app, turn them back on: keep the Piezas plugin enabled if you use it, then open Settings, then Hooks, click Trust all and start a new chat. ',
    'claude-code': 'In the Claude app, turn them back on: keep the Piezas plugin enabled if you use it, then start a new session in this folder and click Trust workspace if it asks. ',
  },
  alsoApp: {
    codex: 'In the Codex app: open Settings, then Hooks, and click Trust all. ',
    'claude-code': 'In the Claude app: start a new session in this folder and click Trust workspace if it asks. ',
  },
};

// guardsOnText — the middle of guardWarning: the app's sentence or the
// terminal's; when that cannot be told, the terminal's and then the app step
// for the tool (both apps, Codex first, when the tool is not known either).
export function guardsOnText({ host, app } = {}) {
  const known = Boolean(GUARDS_ON_TEXT.app[host]);
  if (known && app === true) return GUARDS_ON_TEXT.app[host];
  if (known && app === false) return GUARDS_ON_TEXT.terminal;
  const hosts = known ? [host] : ['codex', 'claude-code'];
  return GUARDS_ON_TEXT.terminal + hosts.map((h) => GUARDS_ON_TEXT.alsoApp[h]).join('');
}

// guardWarning — a plain sentence when this project's guardrails have not run
// recently (hooks off, plugin missing, Node missing), else null. Commands an
// agent runs go through PreToolUse first, so a live session is always fresh.
// The plugin-directory edition ships without hooks by design (OpenAI's
// directory does not accept them), so "turn the checks back on" would point at
// hooks that don't exist. Its build drops this marker next to the engine.
const DIRECTORY_EDITION = existsSync(join(dirname(fileURLToPath(import.meta.url)), 'edition-directory.json'));

export function guardWarning(startDir = process.cwd(), env = process.env) {
  if (DIRECTORY_EDITION) return null;
  const root = findProjectRoot(startDir);
  if (!root) return null;
  try {
    const marker = JSON.parse(readFileSync(join(root, STATE_DIR, GUARD_MARKER), 'utf-8'));
    const age = Date.now() - Date.parse(marker.lastSeen);
    if (marker.active === true && Number.isFinite(age) && age < GUARD_STALE_MS) return null;
  } catch {
    // missing or unreadable marker -> warn below
  }
  return (
    "Piezas safety checks are off in this session, so the app's Piezas rules are not being enforced as it is built. " +
    guardsOnText(agentSurface(env)) +
    'Running this command yourself in a terminal? Then you can ignore this.'
  );
}

// ===========================================================================
// Import: bring an app the owner already has onto Piezas
// ===========================================================================
//
// Many owners arrive with an app already started (Lovable, Claude Code, a
// freelancer). `init --import <folder>` COPIES it into the project folder, never
// touching the original, and starts the same guided flow as a fresh app: the
// description is drafted from what the code does, the owner confirms by seeing
// it, and the build moves it onto Piezas.
//
// The scan sorts what it finds into two lists:
//   must move     — the never-rules (hardNoFindings). The app cannot leave the
//                   build step, and a deploy pauses, until they are gone.
//   can take over — services Piezas can replace (records, sign-in, files,
//                   email). Recommended; the owner decides.
// Findings that came WITH the code are recorded as inherited, so they do not
// stop the owner from describing and previewing the app they already have.
// The build-step hard stop is unchanged: leaving the build requires every
// never-rule fixed, inherited or not.

export const IMPORT_FILE = 'import.json';
export const IMPORT_REL = `${STATE_DIR}/${IMPORT_FILE}`;
export const IMPORT_VERSION = 1;
export const IMPORT_MAX_FILES = 20_000;
export const IMPORT_SKIP_DIRS = new Set([
  'node_modules', '.git', '.hg', '.svn', 'dist', 'build', 'out', '.next', '.nuxt', '.svelte-kit', '.output',
  '.vercel', '.netlify', '.turbo', '.cache', '.parcel-cache', 'coverage', '.piezas', '.expo', '.vite',
]);
export const IMPORT_SKIP_FILES = new Set(['.DS_Store', 'Thumbs.db']);
// A folder holding only these is treated as empty: the AI tool may have created them.
export const IGNORABLE_IN_EMPTY_DIR = new Set(['.DS_Store', '.claude', '.codex']);
export const ENV_TEMPLATE_NAME = /\.(example|sample|template)$/;

export function isSecretEnvFile(name) {
  return name.startsWith('.env') && !ENV_TEMPLATE_NAME.test(name);
}

export function isInsideDir(child, parent) {
  const rel = relative(parent, child);
  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel));
}

export function isEffectivelyEmptyDir(dir) {
  try {
    return readdirSync(dir).every((name) => IGNORABLE_IN_EMPTY_DIR.has(name));
  } catch {
    return true; // missing counts as empty
  }
}

// A path typed or dragged into a terminal: quotes and backslash-escaped spaces.
export function cleanTypedPath(value) {
  let text = String(value ?? '').trim();
  const quoted = /^(['"])(.*)\1$/.exec(text);
  if (quoted) text = quoted[2];
  text = text.replace(/\\ /g, ' ');
  if (text === '~' || text.startsWith('~/')) text = join(homedir(), text.slice(1));
  return text;
}

// importDestination — where the copy goes. An explicit target wins. Otherwise
// the current folder when it is empty (the usual case: the owner opened their
// AI tool in a new folder), else a new folder named after the app.
export function importDestination(source, currentDir, targetArg) {
  const src = resolve(source);
  if (targetArg) return resolve(currentDir, targetArg);
  const name = basename(src);
  const candidates = [currentDir, resolve(currentDir, name), resolve(currentDir, `${name}-piezas`), resolve(dirname(src), `${name}-piezas`)];
  for (const dir of candidates) {
    if (isInsideDir(dir, src)) continue;
    if (isEffectivelyEmptyDir(dir)) return dir;
  }
  throw new Error(`Could not find an empty folder for the copy. Name one: piezas init <new-folder> --import "${source}"`);
}

// copyImportedApp — read-only on the source. Leaves out installed packages,
// history, build output and private settings (.env files; templates are kept).
export function copyImportedApp(source, dest) {
  const src = resolve(source);
  let stats;
  try {
    stats = statSync(src);
  } catch {
    throw new Error(`There is no folder at ${source}. Check the path and try again.`);
  }
  if (!stats.isDirectory()) throw new Error(`${source} is a file, not a folder. Point to the folder that holds the app.`);
  const target = resolve(dest);
  const realSrc = realpathSync(src);
  if (isInsideDir(target, src) || isInsideDir(target, realSrc)) {
    throw new Error('The new project folder cannot be inside the app being imported. Choose a folder next to it instead.');
  }
  if (!isEffectivelyEmptyDir(target)) {
    throw new Error(`${target} already has files in it. Choose an empty or new folder for the imported app.`);
  }
  let count = 0;
  const leftOut = new Set();
  const walk = (from, to) => {
    for (const entry of readdirSync(from, { withFileTypes: true })) {
      const name = entry.name;
      const fromPath = join(from, name);
      if (entry.isSymbolicLink()) {
        leftOut.add('shortcuts (links)');
        continue;
      }
      if (entry.isDirectory()) {
        if (IMPORT_SKIP_DIRS.has(name)) {
          leftOut.add(name);
          continue;
        }
        walk(fromPath, join(to, name));
        continue;
      }
      if (!entry.isFile() || IMPORT_SKIP_FILES.has(name)) continue;
      if (isSecretEnvFile(name)) {
        leftOut.add(name);
        continue;
      }
      count += 1;
      if (count > IMPORT_MAX_FILES) {
        throw new Error(`That folder has more than ${IMPORT_MAX_FILES} files. Point to the app's own folder, not a folder that holds many projects.`);
      }
      mkdirSync(to, { recursive: true });
      copyFileSync(fromPath, join(to, name));
    }
  };
  mkdirSync(target, { recursive: true });
  walk(src, target);
  if (count === 0) throw new Error(`${source} has no files to import.`);
  return { source: src, dest: target, files: count, leftOut: [...leftOut].sort() };
}

// --- the scan -------------------------------------------------------------

export const TAKEOVER_TEXT = {
  records: {
    title: 'Business records',
    piezas: 'Piezas keeps your records in one safe place, backed up, with the access rules your app needs.',
  },
  'sign-in': {
    title: 'Sign-in and accounts',
    piezas: 'Piezas handles sign-up, sign-in and password resets, so the app never stores passwords itself.',
  },
  files: {
    title: 'Files and uploads',
    piezas: 'Piezas stores uploaded files and documents, with access controls.',
  },
  email: {
    title: 'Email',
    piezas: "Piezas sends the app's account and transactional emails, such as confirmations and password resets.",
  },
};
export const TAKEOVER_ORDER = ['records', 'sign-in', 'files', 'email'];

export const SIGN_IN_PACKAGES = [
  [/^(next-auth|@auth\/)/, 'Auth.js'],
  [/^@clerk\//, 'Clerk'],
  [/^@auth0\//, 'Auth0'],
  [/^@kinde-oss\//, 'Kinde'],
  [/^(lucia|passport|bcrypt|bcryptjs|argon2|jsonwebtoken|iron-session)$/, 'its own sign-in code'],
];
export const FILE_PACKAGES = [
  [/^(@aws-sdk\/client-s3|aws-sdk)$/, 'Amazon S3'],
  [/^@vercel\/blob$/, 'Vercel Blob'],
  [/^(uploadthing|@uploadthing\/)/, 'UploadThing'],
  [/^cloudinary$/, 'Cloudinary'],
  [/^@google-cloud\/storage$/, 'Google Cloud Storage'],
  [/^multer$/, 'its own upload handling'],
];
export const EMAIL_PACKAGES = [
  [/^nodemailer$/, 'its own email sending'],
  [/^resend$/, 'Resend'],
  [/^@sendgrid\/mail$/, 'SendGrid'],
  [/^postmark$/, 'Postmark'],
  [/^mailgun\.js$/, 'Mailgun'],
  [/^@mailchimp\/mailchimp_transactional$/, 'Mailchimp'],
  [/^(@emailjs\/browser|emailjs-com)$/, 'EmailJS'],
];
export const CONNECTS_TO = [
  [/^(stripe|@stripe\/)/, 'Stripe'],
  [/^openai$/, 'OpenAI'],
  [/^@anthropic-ai\/sdk$/, 'Anthropic'],
  [/^twilio$/, 'Twilio'],
  [/^googleapis$/, 'Google'],
  [/^(@google\/generative-ai|@google\/genai)$/, 'Google Gemini'],
];
export const BROWSER_AUTH_KEY = /localStorage\.setItem\(\s*['"`][^'"`]*(user|auth|session|token|login|account)[^'"`]*['"`]/i;
export const BROWSER_RECORD_KEY = /localStorage\.setItem\(\s*['"`]([^'"`]+)['"`]\s*,\s*JSON\.stringify/g;
export const UI_STORAGE_KEY = /theme|lang|locale|sidebar|tour|onboard|dismiss|cookie|consent|prefer|setting|user|auth|session|token|login|account/i;

export function hardNoKey(finding) {
  return `${finding.code}|${finding.file ?? ''}`;
}

export function packageDeps(projectDir) {
  const pkg = packageJson(projectDir) || {};
  return Object.keys({ ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) });
}

export function firstMatch(table, name) {
  const hit = table.find(([re]) => re.test(name));
  return hit ? hit[1] : null;
}

export function joinWords(items) {
  const list = [...new Set(items)];
  if (list.length <= 1) return list.join('');
  return `${list.slice(0, -1).join(', ')} and ${list[list.length - 1]}`;
}

export function mustMoveItems(findings) {
  const groups = new Map();
  for (const f of findings) {
    const id = f.code === 'PZ020' ? 'own-database' : ['PZ004', 'PZ005', 'PZ006'].includes(f.code) ? 'provider-tokens' : 'key-in-browser';
    const group = groups.get(id) ?? { id, files: new Set(), names: new Set(), codes: new Set() };
    if (f.file) group.files.add(f.file);
    group.codes.add(f.code);
    const name = /^([A-Z][A-Z0-9_]{2,})\b/.exec(f.message || '');
    if (id === 'key-in-browser' && name) group.names.add(name[1]);
    groups.set(id, group);
  }
  const items = [];
  for (const g of groups.values()) {
    const files = [...g.files].sort();
    if (g.id === 'own-database') {
      items.push({
        id: g.id,
        title: 'The app keeps its own database',
        found: 'Records are stored in a database the app runs itself, which nothing else can see or back up.',
        piezas: 'Your records move to Piezas, where they are backed up and kept in one place.',
        files,
        codes: [...g.codes],
      });
    } else if (g.id === 'key-in-browser') {
      const names = [...g.names];
      items.push({
        id: g.id,
        title: 'A key is built into the pages people open',
        found: `${names.length ? joinWords(names) : 'A key'} can be copied by anyone who opens the app.`,
        piezas: 'The key moves to the server side, where visitors cannot see it. Replace the key afterwards, since it may already have been copied.',
        files,
        codes: [...g.codes],
      });
    } else {
      items.push({
        id: g.id,
        title: 'The app stores access passes for other services',
        found: 'The app keeps the passes that let it act in other services (for example Google).',
        piezas: 'Piezas keeps those connections, and the app keeps only a reference to them.',
        files,
        codes: [...g.codes],
      });
    }
  }
  return items;
}

// detectTakeovers — services Piezas can replace, from the packages the app
// uses and from what its code does. Plain sources ("Supabase", "the browser").
export function detectTakeovers(projectDir, files) {
  const found = new Map(); // id -> { sources:Set, files:Set }
  const add = (id, source, file) => {
    const entry = found.get(id) ?? { sources: new Set(), files: new Set() };
    entry.sources.add(source);
    if (file) entry.files.add(file);
    found.set(id, entry);
  };
  const deps = packageDeps(projectDir);
  const hasSupabase = deps.some((d) => d.startsWith('@supabase/'));
  const hasFirebase = deps.some((d) => d === 'firebase' || d === 'firebase-admin');
  for (const dep of deps) {
    const signIn = firstMatch(SIGN_IN_PACKAGES, dep);
    if (signIn) add('sign-in', signIn);
    const fileStore = firstMatch(FILE_PACKAGES, dep);
    if (fileStore) add('files', fileStore);
    const email = firstMatch(EMAIL_PACKAGES, dep);
    if (email) add('email', email);
  }
  let supabaseUse = false;
  let firebaseUse = false;
  for (const { filePath, rel } of appSourceFiles(projectDir, files)) {
    const content = readFileSync(filePath, 'utf-8');
    if (/supabase/i.test(content)) {
      if (/(?<!storage)\.from\(\s*['"`]/.test(content)) { add('records', 'Supabase', rel); supabaseUse = true; }
      if (/\.auth\./.test(content)) { add('sign-in', 'Supabase', rel); supabaseUse = true; }
      if (/\.storage\b/.test(content)) { add('files', 'Supabase', rel); supabaseUse = true; }
    }
    if (/firebase/i.test(content)) {
      if (/firebase\/firestore|getFirestore\(|firestore\(\)/.test(content)) { add('records', 'Firebase', rel); firebaseUse = true; }
      if (/firebase\/auth|getAuth\(/.test(content)) { add('sign-in', 'Firebase', rel); firebaseUse = true; }
      if (/firebase\/storage|getStorage\(/.test(content)) { add('files', 'Firebase', rel); firebaseUse = true; }
    }
    if (BROWSER_AUTH_KEY.test(content) && /password/i.test(content)) add('sign-in', 'the browser', rel);
    BROWSER_RECORD_KEY.lastIndex = 0;
    let m = BROWSER_RECORD_KEY.exec(content);
    while (m) {
      if (!UI_STORAGE_KEY.test(m[1])) add('records', 'the browser', rel);
      m = BROWSER_RECORD_KEY.exec(content);
    }
  }
  if (files.some((f) => /(^|\/)supabase\/migrations\/[^/]+\.sql$/.test(normalizeRel(projectDir, f)))) add('records', 'Supabase');
  if (hasSupabase && !supabaseUse && !found.has('records')) add('records', 'Supabase');
  if (hasFirebase && !firebaseUse && !found.has('records')) add('records', 'Firebase');

  const SOURCE_PHRASE = { records: 'Records are kept in', 'sign-in': 'Sign-in is handled by', files: 'Files are stored with', email: 'Email is sent through' };
  return TAKEOVER_ORDER.filter((id) => found.has(id)).map((id) => {
    const entry = found.get(id);
    const sources = [...entry.sources];
    const phrase = sources.map((s) => {
      if (s !== 'the browser') return s;
      return id === 'records' ? 'the browser only (they disappear when the browser is cleared)' : 'accounts saved in the browser';
    });
    return {
      id,
      title: TAKEOVER_TEXT[id].title,
      found: `${SOURCE_PHRASE[id]} ${joinWords(phrase)}.`,
      piezas: TAKEOVER_TEXT[id].piezas,
      sources,
      files: [...entry.files].sort(),
      choice: null,
    };
  });
}

export function routeFromAppPage(rel) {
  const parts = rel.replace(/^src\//, '').split('/');
  parts.shift(); // app
  parts.pop(); // page.tsx
  const route = parts.filter((p) => !/^\(.*\)$/.test(p)).join('/');
  return `/${route}`;
}

// importInventory — what the code shows, to seed the description: screens,
// kinds of records, sign-in and outside services. Heuristic, never exhaustive.
export function importInventory(projectDir, files, takeovers) {
  const deps = packageDeps(projectDir);
  const isNext = deps.includes('next');
  const screens = [];
  const records = new Set();
  const seenScreen = new Set();
  const addScreen = (name, file) => {
    const key = `${name}|${file}`;
    if (seenScreen.has(key) || screens.length >= 40) return;
    seenScreen.add(key);
    screens.push({ name, file });
  };
  for (const filePath of files) {
    const rel = normalizeRel(projectDir, filePath);
    if (/\.sql$/.test(rel)) {
      const content = readFileSync(filePath, 'utf-8');
      for (const m of content.matchAll(/create\s+table\s+(?:if\s+not\s+exists\s+)?(?:"?public"?\.)?"?([A-Za-z_][\w]*)"?/gi)) records.add(m[1]);
    }
  }
  for (const { filePath, rel } of appSourceFiles(projectDir, files)) {
    const content = readFileSync(filePath, 'utf-8');
    if (/(^|\/)app\/(.*\/)?page\.[cm]?[jt]sx?$/.test(rel)) addScreen(routeFromAppPage(rel), rel);
    else if (isNext && /(^|\/)pages\/(?!api\/|_)[^]*\.[jt]sx?$/.test(rel)) {
      const route = rel.replace(/^(src\/)?pages\//, '').replace(/\.[jt]sx?$/, '').replace(/(^|\/)index$/, '');
      addScreen(`/${route}`, rel);
    } else if (!isNext && /(^|\/)(pages|screens|views)\/[^/]+\.[jt]sx$/.test(rel)) {
      addScreen(basename(rel).replace(/\.[jt]sx$/, ''), rel);
    }
    if (/react-router|createBrowserRouter/.test(content)) {
      for (const m of content.matchAll(/<Route\b[^>]*\bpath=["'`]([^"'`]+)["'`]/g)) addScreen(m[1], rel);
      for (const m of content.matchAll(/\bpath:\s*["'`](\/[^"'`]*)["'`]/g)) addScreen(m[1], rel);
    }
    if (/supabase/i.test(content)) {
      for (const m of content.matchAll(/(?<!storage)\.from\(\s*['"`]([A-Za-z_][\w-]*)['"`]\s*\)/g)) records.add(m[1]);
      for (const m of content.matchAll(/^\s*([a-z_][\w]*):\s*\{\s*\n\s*Row:/gm)) records.add(m[1]);
    }
    for (const m of content.matchAll(/collection\(\s*\w+\s*,\s*['"`]([\w-]+)['"`]/g)) records.add(m[1]);
  }
  // Routes from a router say more than page file names; keep names only when
  // no routes were found.
  if (screens.some((s) => s.name.startsWith('/'))) {
    for (let i = screens.length - 1; i >= 0; i -= 1) if (!screens[i].name.startsWith('/')) screens.splice(i, 1);
  }
  const signIn = (takeovers.find((t) => t.id === 'sign-in')?.sources ?? []).map((s) => (s === 'the browser' ? 'accounts saved in the browser' : s));
  const connects = [...new Set(deps.map((d) => firstMatch(CONNECTS_TO, d)).filter(Boolean))];
  return { screens, records: [...records].sort().slice(0, 40), signIn, connectsTo: connects };
}

export function importScan(projectDir) {
  const dir = resolve(projectDir);
  const files = listFiles(dir);
  const hardNo = hardNoFindings(dir);
  const canTakeOver = detectTakeovers(dir, files);
  return {
    mustMove: mustMoveItems(hardNo),
    canTakeOver,
    inventory: importInventory(dir, files, canTakeOver),
    hardNo,
  };
}

// customerDataFromScan — "real customer data?" from the code: "no" only on
// positive evidence of nothing; otherwise open (the owner is asked), with the
// signs found for the AI. An answer from the owner is never changed here.
export function customerDataFromScan(data, root) {
  if (data.customerData != null && data.customerDataVia !== 'scan') return {};
  const evidence = dataStoreEvidence(root);
  if (!foundDataStore(data) && !evidence.length) return { customerData: 'no', customerDataVia: 'scan', dataEvidence: [] };
  return { customerData: null, customerDataVia: null, dataEvidence: evidence };
}

export function readImportState(startDir) {
  const root = findProjectRoot(startDir);
  if (!root) return null;
  try {
    const parsed = JSON.parse(readFileSync(join(root, STATE_DIR, IMPORT_FILE), 'utf-8'));
    return parsed && parsed.version === IMPORT_VERSION ? parsed : null;
  } catch {
    return null;
  }
}

export function writeImportState(root, data) {
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  writeFileSync(join(root, STATE_DIR, IMPORT_FILE), `${JSON.stringify(data, null, 2)}\n`);
}

// recordImport — the first scan of a freshly copied app. The never-rule
// findings present NOW are what the owner brought; they are the baseline.
export function recordImport(root, copy) {
  const scan = importScan(root);
  const now = new Date().toISOString();
  const data = {
    version: IMPORT_VERSION,
    source: copy.source,
    importedAt: now,
    scannedAt: now,
    inherited: [...new Set(scan.hardNo.map(hardNoKey))].sort(),
    mustMove: scan.mustMove,
    canTakeOver: scan.canTakeOver,
    customerData: null,
    inventory: scan.inventory,
  };
  // No data store in the code at all (browser-only, sample data): there is no
  // real customer data to move, so the question is not asked (Spec Part 2,
  // #24); the owner is told in one line (NO_DATA_STORE_LINE).
  Object.assign(data, customerDataFromScan(data, root));
  writeImportState(root, data);
  return data;
}

// foundDataStore — does the imported code keep records anywhere real (its own
// database, or a hosted one such as Supabase or Firebase)? Records only in the
// browser are not a data store. With the project folder, any sign of a
// database or of server code counts too (dataStoreEvidence): "no real
// customer data" is assumed only on positive evidence of nothing.
export function foundDataStore(data, dir) {
  if ((data?.mustMove || []).some((i) => i.id === 'own-database')) return true;
  const records = (data?.canTakeOver || []).find((i) => i.id === 'records');
  if (records && (records.sources || []).some((s) => s !== 'the browser')) return true;
  return dir ? dataStoreEvidence(dir).length > 0 : false;
}

// What the owner is told when "real customer data?" is answered from the code.
export const NO_DATA_STORE_LINE = "I found no database in the code, so I'm treating it as having no real customer data yet; tell me if that's wrong.";

export const DATA_STORE_PACKAGES = new Set([
  '@prisma/client', 'prisma', 'better-sqlite3', 'sqlite3', 'sqlite', 'sql.js', 'drizzle-orm', 'knex', 'kysely', 'mongoose', 'mongodb',
  'mysql', 'mysql2', 'pg', 'postgres', '@neondatabase/serverless', '@libsql/client', '@vercel/postgres', '@vercel/kv',
  '@planetscale/database', 'sequelize', 'typeorm', '@mikro-orm/core', 'objection', 'airtable', 'redis', 'ioredis',
  '@upstash/redis', '@supabase/supabase-js', 'firebase', 'firebase-admin', '@google-cloud/firestore', 'lowdb', 'nedb',
  'pouchdb', 'dynamoose', '@aws-sdk/client-dynamodb', '@aws-sdk/lib-dynamodb', 'faunadb', 'convex', '@electric-sql/pglite',
  'neo4j-driver', 'cassandra-driver', 'couchbase', 'pg-promise', 'mssql', 'tedious', 'oracledb', 'pocketbase', 'appwrite',
  'node-appwrite', 'googleapis', '@googleapis/sheets', 'google-spreadsheet', '@notionhq/client', '@aws-sdk/client-rds-data',
  '@google-cloud/datastore', '@google-cloud/spanner', '@google-cloud/bigquery', 'edgedb', 'gel', 'surrealdb', 'rxdb', 'instantdb',
  '@instantdb/react', '@instantdb/admin',
]);
// Scopes whose packages keep records (or real customer accounts) elsewhere.
const DATA_STORE_SCOPES = ['@clerk/', '@auth0/', '@supabase/', '@prisma/', '@libsql/', '@upstash/', '@planetscale/', '@neondatabase/', '@vercel/postgres', '@electric-sql/'];
const isDataStorePackage = (dep) => DATA_STORE_PACKAGES.has(dep) || DATA_STORE_SCOPES.some((p) => dep.startsWith(p));
// A server stack other than Node or Python (Rails, Laravel/PHP, Go, Java,
// .NET, Cloudflare Workers): not a browser-only project, so the owner is asked.
const OTHER_SERVER_FILES = new Set(['Gemfile', 'composer.json', 'go.mod', 'pom.xml', 'build.gradle', 'build.gradle.kts', 'wrangler.toml', 'wrangler.json', 'wrangler.jsonc', 'manage.py', 'artisan', 'mix.exs', 'Cargo.toml']);
const GEM_DATA = /^\s*gem\s+['"](pg|mysql2|sqlite3|activerecord|mongoid|redis|sequel|trilogy|rails)['"]/m;
const PHP_DATA = /"(illuminate\/database|laravel\/framework|doctrine\/(?:orm|dbal)|mongodb\/mongodb|predis\/predis|cakephp\/cakephp|symfony\/(?:orm-pack|doctrine-bridge))"/;
const GO_DATA = /(gorm\.io\/|github\.com\/jackc\/pgx|github\.com\/lib\/pq|go\.mongodb\.org\/|github\.com\/go-sql-driver\/mysql|github\.com\/mattn\/go-sqlite3|modernc\.org\/sqlite|"database\/sql"|entgo\.io\/|github\.com\/redis\/go-redis|github\.com\/jmoiron\/sqlx)/;
const WRANGLER_DATA = /\b(d1_databases|kv_namespaces|r2_buckets|durable_objects|hyperdrive)\b/;
const SERVER_PACKAGES = new Set(['express', 'fastify', 'koa', 'hono', '@nestjs/core', '@hapi/hapi', 'restify', 'next-auth']);
const PY_DATA = /^(?:sqlalchemy|flask[-_]sqlalchemy|sqlmodel|psycopg2?(?:[-_]binary)?|psycopg|pymongo|motor|mysqlclient|pymysql|mysql[-_]connector(?:[-_]python)?|peewee|django|tortoise[-_]orm|redis|asyncpg|aiosqlite|databases|supabase|firebase[-_]admin|prisma|pyairtable|airtable|dataset|pony|tinydb)\b/i;
const PY_SERVER = /^(?:flask|fastapi|django|starlette|bottle|tornado|aiohttp|sanic)\b/i;
const PY_IMPORT = /^\s*(?:import|from)\s+(sqlite3|psycopg2?|psycopg|pymongo|sqlalchemy|mysql|MySQLdb|pymysql|peewee|redis|asyncpg|aiosqlite|motor|sqlmodel|tinydb|shelve|dbm|supabase|firebase_admin)\b/m;
const DB_FILE = /\.(?:db|db3|sqlite|sqlite3|mdb|accdb)$/i;
const DB_ENV_NAME = /^(?:export\s+)?((?:[A-Z0-9_]*_)?(?:DATABASE_URL|DATABASE_URI|DB_URL|DB_URI|DB_HOST|DB_NAME|DB_CONNECTION|DB_DATABASE|DB_USERNAME|DB_PASSWORD)|POCKETBASE[A-Z0-9_]*|APPWRITE[A-Z0-9_]*|CLERK_SECRET_KEY|MONGO[A-Z0-9_]*|SUPABASE_URL|POSTGRES[A-Z0-9_]*|PG(?:HOST|DATABASE|USER)|MYSQL[A-Z0-9_]*|REDIS[A-Z0-9_]*|TURSO[A-Z0-9_]*|NEON[A-Z0-9_]*|FIREBASE[A-Z0-9_]*|AIRTABLE[A-Z0-9_]*|KV_URL|KV_REST_API_URL)\s*=/m;
const EVIDENCE_SKIP = new Set(['node_modules', '.git', '.next', 'dist', 'build', 'out', '.piezas', '.venv', 'venv', '__pycache__', '.turbo', '.vercel', 'coverage']);

// dataStoreEvidence — every sign in the project that it may keep records
// somewhere real: a database or data-service dependency (npm or Python), a
// database file, a database setting name in an .env file, a Python database
// import, or server code (an API route, a server file, a server framework).
export function dataStoreEvidence(dir) {
  const found = [];
  const add = (why) => { if (found.length < 12 && !found.includes(why)) found.push(why); };
  let seen = 0;
  const walk = (d, depth) => {
    let entries;
    try { entries = readdirSync(d, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      if (seen++ > 20000) return;
      const full = join(d, e.name);
      const rel = relative(dir, full).split('\\').join('/');
      if (e.isSymbolicLink()) continue;
      if (e.isDirectory()) {
        if (!EVIDENCE_SKIP.has(e.name) && depth < 12) walk(full, depth + 1);
        continue;
      }
      if (!e.isFile()) continue;
      const name = e.name;
      if (DB_FILE.test(name)) { add(`a database file (${rel})`); continue; }
      if (/(^|\/)(?:app|src\/app)\/(?:.*\/)?api\/.*route\.[cm]?[jt]s$/.test(rel) || /(^|\/)(?:src\/)?pages\/api\//.test(rel)
        || /^(?:server|src\/server)\.[cm]?[jt]s$/.test(rel) || /^server\//.test(rel)) add(`server code (${rel})`);
      let text = null;
      const read = () => {
        if (text !== null) return text;
        try { text = statSync(full).size < 512 * 1024 ? readFileSync(full, 'utf-8') : ''; } catch { text = ''; }
        return text;
      };
      if (name === 'package.json') {
        let pkg = null;
        try { pkg = JSON.parse(read()); } catch { pkg = null; }
        const deps = Object.keys({ ...(pkg?.dependencies ?? {}), ...(pkg?.devDependencies ?? {}) });
        for (const dep of deps) {
          if (isDataStorePackage(dep)) add(`the ${dep} package`);
          else if (SERVER_PACKAGES.has(dep)) add(`server code (the ${dep} package)`);
        }
      } else if (/^(?:requirements[^/]*\.txt|pyproject\.toml|Pipfile|setup\.py|setup\.cfg)$/.test(name)) {
        // One name per line, or several in an inline array
        // (dependencies = ["django>=5", "psycopg[binary]"]).
        const words = [];
        for (const line of read().split('\n')) {
          words.push(line.trim().replace(/^["']/, ''));
          for (const m of line.matchAll(/["']([A-Za-z][A-Za-z0-9_.-]*)/g)) words.push(m[1]);
        }
        for (const word of words) {
          if (PY_DATA.test(word)) add(`the ${word.split(/[\s=<>~!;\[,"']/)[0]} package`);
          else if (PY_SERVER.test(word)) add(`server code (the ${word.split(/[\s=<>~!;\[,"']/)[0]} package)`);
        }
      } else if (OTHER_SERVER_FILES.has(name)) {
        const body = read();
        const gem = name === 'Gemfile' ? GEM_DATA.exec(body) : null;
        const php = name === 'composer.json' ? PHP_DATA.exec(body) : null;
        const go = name === 'go.mod' ? GO_DATA.exec(body) : null;
        const worker = /^wrangler\./.test(name) ? WRANGLER_DATA.exec(body) : null;
        if (gem) add(`the ${gem[1]} gem`);
        else if (php) add(`the ${php[1]} package`);
        else if (go) add(`a database package in go.mod (${go[1].replace(/"/g, '')})`);
        else if (worker) add(`a Cloudflare ${worker[1]} binding (${rel})`);
        else add(`server code (${rel})`);
      } else if (/^database\.ya?ml$/.test(name) || /\.(?:csproj|fsproj)$/.test(name)) {
        add(`server code (${rel})`);
      } else if (/\.go$/.test(name) && GO_DATA.test(read())) {
        add(`a database package in ${rel}`);
      } else if (/\.py$/.test(name)) {
        const m = PY_IMPORT.exec(read());
        if (m) add(`${m[1]} in ${rel}`);
        else if (/^\s*DATABASES\s*=/m.test(read())) add(`a database setting (DATABASES in ${rel})`);
        else if (/\b(?:Flask|FastAPI)\s*\(/.test(read())) add(`server code (${rel})`);
      } else if (/^\.env(?:\..+)?$/.test(name)) {
        const m = DB_ENV_NAME.exec(read());
        if (m) add(`a database setting (${m[1]} in ${name})`);
      } else if (/\.[cm]?[jt]sx?$/.test(name) && /^\s*['"]use server['"]/m.test(read())) {
        add(`server code (${rel})`);
      } else if (/\.[cm]?[jt]sx?$/.test(name) && /from\s+['"](?:bun:sqlite|node:sqlite)['"]|require\(\s*['"]node:sqlite['"]\s*\)/.test(read())) {
        add(`a local database (${rel})`);
      }
    }
  };
  walk(resolve(dir), 0);
  return found;
}

// newHardNoFindings — never-rule findings the owner did NOT bring with the
// code. Inherited ones are the build's work order, not a reason to stop them
// describing or previewing their own app.
export function newHardNoFindings(root) {
  const all = hardNoFindings(root);
  const imported = readImportState(root);
  if (!imported || !Array.isArray(imported.inherited)) return all;
  const baseline = new Set(imported.inherited);
  return all.filter((f) => !baseline.has(hardNoKey(f)));
}

// importGaps — what must be settled before the build (owner's choices) and
// before going live (every accepted replacement actually done).
export function importGaps(root, phase) {
  const imported = readImportState(root);
  if (!imported) return [];
  const gaps = [];
  if (phase === 'mock') {
    const open = (imported.canTakeOver || []).filter((item) => item.choice !== 'take' && item.choice !== 'keep');
    if (open.length > 0) {
      gaps.push(gap('IMPORT', `ask the owner which services Piezas should take over (${open.map((i) => i.id).join(', ')}): run \`piezas import ask all\` and ask exactly the one question it prints; their own reply is recorded automatically ("you decide" is recorded as your recommendation)`));
    }
    if (imported.customerData !== 'yes' && imported.customerData !== 'no') {
      gaps.push(gap('IMPORT', 'ask the owner "Does this app already hold real customer data?": run `piezas import ask customer-data` and ask exactly the question it prints; their own reply is recorded automatically'));
    }
  }
  if (phase === 'build') {
    const still = detectTakeovers(root, listFiles(root));
    for (const item of imported.canTakeOver || []) {
      if (item.choice !== 'take') continue;
      const now = still.find((s) => s.id === item.id);
      const left = now ? now.sources.filter((s) => item.sources.includes(s)) : [];
      if (left.length > 0) gaps.push(gap('IMPORT', `${item.title} was to move to Piezas, but the app still uses ${joinWords(left)}`));
    }
  }
  return gaps;
}

export function importItemLines(item, marker) {
  const lines = [`  ${marker} ${item.title} — ${item.found}`, `     Piezas: ${item.piezas}`];
  if (item.files?.length) lines.push(`     Where: ${item.files.slice(0, 6).join(', ')}${item.files.length > 6 ? ', …' : ''}`);
  return lines;
}

export function formatImportScan(data) {
  const inv = data.inventory || {};
  const lines = ['What the code shows (draft the description from this and from reading the code; mark each requirement "found in your code: <file>"):'];
  lines.push(`  Screens: ${inv.screens?.length ? inv.screens.map((s) => `${s.name} (${s.file})`).join(', ') : 'none found — read the code'}`);
  lines.push(`  Kinds of records: ${inv.records?.length ? inv.records.join(', ') : 'none found — read the code'}`);
  lines.push(`  Sign-in: ${inv.signIn?.length ? joinWords(inv.signIn) : 'none found'}`);
  if (inv.connectsTo?.length) lines.push(`  Connects to: ${joinWords(inv.connectsTo)}`);
  lines.push('');
  lines.push('Must move to Piezas (the app cannot go live until these are moved):');
  if (data.mustMove?.length) data.mustMove.forEach((item, i) => lines.push(...importItemLines(item, `${i + 1}.`)));
  else lines.push('  nothing');
  lines.push('');
  lines.push('Piezas can take this over (recommended; the owner decides):');
  if (data.canTakeOver?.length) {
    for (const item of data.canTakeOver) {
      const choice = item.choice === 'take' ? '[owner: move to Piezas]' : item.choice === 'keep' ? '[owner: keep as is]' : '[owner: not asked yet]';
      lines.push(...importItemLines({ ...item, title: `${item.title} (${item.id}) ${choice}` }, '-'));
    }
  } else {
    lines.push('  nothing');
  }
  lines.push('');
  const data_ = data.customerData === 'yes' ? 'yes (moving that data is a later, separate step — do not copy or migrate it now)' : data.customerData === 'no' ? 'no' : 'not asked yet';
  lines.push(`Does this app already hold real customer data? ${data_}`);
  if (data.customerData === 'no' && data.customerDataVia === 'scan') {
    lines.push(`  (Found no database or server code. Tell the owner, in these words: "${NO_DATA_STORE_LINE}" If they say it is wrong, run \`piezas import ask customer-data\`.)`);
  } else if (data.customerData == null && data.dataEvidence?.length) {
    lines.push(`  (Ask it: the code shows ${joinWords(data.dataEvidence.slice(0, 4))}.)`);
  }
  return lines;
}

export function importPlanLines(data) {
  const lines = [];
  for (const item of data.mustMove || []) lines.push(`- Must move: ${item.title}. ${item.piezas}`);
  for (const item of data.canTakeOver || []) {
    if (item.choice === 'take') lines.push(`- Move to Piezas (owner's choice): ${item.title} from ${joinWords(item.sources)}. ${item.piezas}`);
  }
  for (const item of data.canTakeOver || []) {
    if (item.choice === 'keep') lines.push(`- Keep as is (owner's choice): ${item.title} with ${joinWords(item.sources)}.`);
  }
  if (data.customerData === 'yes') {
    lines.push('- Existing customer data stays where it is for now. Moving it is a separate, later step: do not copy, export or migrate any data.');
  }
  return lines;
}

export function importCommand(sub, startDir = process.cwd(), options = {}) {
  const root = findProjectRoot(startDir);
  const fail = (message) => ({ exitCode: 1, json: { command: `import ${sub}`, ok: false, error: message }, output: [message] });
  if (!root) return fail('There is no Piezas project here yet. To bring in an existing app: piezas init --import <folder>');
  const current = readImportState(root);
  if (!current) return fail('This project was not imported from existing code, so there is nothing to scan or choose. (Start an import with: piezas init --import <folder>)');

  if (sub === 'scan') {
    const scan = importScan(root);
    // Rescans refresh what is found but never widen the inherited baseline:
    // a never-rule broken after the import is new, whoever broke it.
    const previous = new Map((current.canTakeOver || []).map((i) => [i.id, i]));
    const data = {
      ...current,
      scannedAt: new Date().toISOString(),
      mustMove: scan.mustMove,
      canTakeOver: scan.canTakeOver.map((item) => {
        const before = previous.get(item.id);
        return before?.choice ? { ...item, choice: before.choice } : item;
      }),
      inventory: scan.inventory,
    };
    // An accepted replacement that is now done stays visible as decided.
    for (const [id, before] of previous) {
      if (!data.canTakeOver.some((i) => i.id === id) && before.choice) data.canTakeOver.push({ ...before, done: true });
    }
    // Re-evaluated on every rescan while the "no" came from the code.
    Object.assign(data, customerDataFromScan(data, root));
    writeImportState(root, data);
    return { exitCode: 0, json: { command: 'import scan', ok: true, ...data }, output: formatImportScan(data) };
  }

  if (sub === 'ask') {
    const item = options.item;
    const question = importQuestion(current, item);
    if (!question) {
      const ids = (current.canTakeOver || []).map((i) => i.id);
      return fail(`Ask about one of: ${[...ids, ...(ids.length > 1 ? ['all'] : []), 'customer-data'].join(', ')}.`);
    }
    const data = { ...current, pendingQuestion: { id: item, askedAt: new Date().toISOString() } };
    writeImportState(root, data);
    return {
      exitCode: 0,
      json: { command: 'import ask', ok: true, item, question },
      output: [
        'Ask the owner exactly this, then stop and wait for their reply (it is recorded automatically from their own message):',
        '',
        question,
      ],
    };
  }

  if (sub === 'choose') {
    // Inside an AI tool the owner answers in the chat and the hook records it;
    // the AI never records a choice on its own. Where no hooks run (the plugin
    // directory build), the AI may relay the owner's exact words with
    // --owner-reply; the record keeps the quote and says it was relayed.
    const ownerReply = typeof options.ownerReply === 'string' ? options.ownerReply.trim() : '';
    if (inAiTool(options.env ?? process.env) && !ownerReply) {
      return fail('The owner\'s choices are recorded from their own replies. Run `piezas import ask <item>`, ask the question it prints, and wait for their answer.');
    }
    // "you decide" for take-over items is "go with your recommendation"
    // (Spec Part 2, #23); for real customer data it is not an answer.
    const replyText = ownerReply.toLowerCase().replace(/[’]/g, "'").replace(/\s+/g, ' ').trim();
    const handsBack = Boolean(ownerReply && HANDS_BACK.test(replyText) && !replyText.includes('?'));
    if (handsBack && options.customerData !== undefined) {
      return fail('"' + ownerReply + '" does not say whether the app holds real customer data. Ask the owner that one plainly.');
    }
    const items = current.canTakeOver || [];
    const ids = new Set(items.map((i) => i.id));
    const list = (value) => (Array.isArray(value) ? value : value === undefined || value === true ? [] : [value])
      .flatMap((v) => String(v).split(','))
      .map((v) => v.trim())
      .filter(Boolean);
    let take = list(options.take);
    let keep = list(options.keep);
    const unknown = [...take, ...keep].filter((id) => !ids.has(id));
    if (unknown.length) return fail(`Unknown item(s): ${unknown.join(', ')}. Choose from: ${[...ids].join(', ') || 'none'}.`);
    const both = take.filter((id) => keep.includes(id));
    if (both.length) return fail(`${both.join(', ')} cannot be both taken over and kept.`);
    if (handsBack) {
      // "You decide" is the recommendation: every item moves. Never the AI's
      // own pick labelled as the recommendation.
      if (keep.length) return fail(`"${ownerReply}" hands the choice back, which means the recommendation: move everything. Drop --keep, or ask the owner which to keep.`);
      take = [...ids];
      keep = [];
    } else if (ownerReply && (take.length || keep.length)) {
      // The relayed words must say what the flags say.
      // Either the batched answer, item for item, or (a one-item question) a
      // reply that names each flagged item and says the same for it.
      const read = readBatchAnswer(items, replyText);
      const flags = Object.fromEntries(items.map((i) => [i.id, take.includes(i.id) ? 'take' : keep.includes(i.id) ? 'keep' : undefined]));
      const batchOk = read && items.every((i) => read[i.id] === flags[i.id]);
      const named = items.filter((i) => flags[i.id]);
      const perItemOk = !BATCH_HEDGE.test(replyText) && named.every((i) => itemMentioned(i, replyText) && readOwnerAnswer(i.id, replyText) === flags[i.id]);
      if (!batchOk && !perItemOk) {
        return fail(`The owner's words ("${ownerReply}") do not say exactly that. Relay what they said, with --take/--keep matching it, or ask them again.`);
      }
    }
    if (ownerReply && !handsBack && options.customerData !== undefined
      && readOwnerAnswer('customer-data', replyText) !== String(options.customerData).trim().toLowerCase()) {
      return fail(`The owner's words ("${ownerReply}") do not say --customer-data ${options.customerData}. Relay what they said, or ask them again.`);
    }
    let customerData = current.customerData;
    if (options.customerData !== undefined) {
      const answer = String(options.customerData).trim().toLowerCase();
      if (!['yes', 'no'].includes(answer)) return fail('--customer-data takes yes or no.');
      customerData = answer;
    }
    const data = {
      ...current,
      canTakeOver: (current.canTakeOver || []).map((item) => (
        take.includes(item.id) ? { ...item, choice: 'take' } : keep.includes(item.id) ? { ...item, choice: 'keep' } : item
      )),
      customerData,
      ...(options.customerData !== undefined ? { customerDataVia: ownerReply ? 'relayed' : 'owner' } : {}),
      dataMigration: customerData === 'yes' ? 'later' : null,
      decidedAt: new Date().toISOString(),
      ...(ownerReply ? { decidedVia: handsBack ? 'recommendation' : 'relayed', ownerReply } : {}),
    };
    writeImportState(root, data);
    return { exitCode: 0, json: { command: 'import choose', ok: true, ...data }, output: ['recorded.', ...importPlanLines(data)] };
  }

  if (sub === 'plan') {
    const lines = importPlanLines(current);
    return {
      exitCode: 0,
      json: { command: 'import plan', ok: true, plan: lines },
      output: lines.length ? ['Build plan for this imported app:', ...lines] : ['Nothing needs to move: the app already follows the Piezas rules.'],
    };
  }
  return fail(`Unknown import command "${sub}". Use: piezas import scan | ask | choose | plan`);
}

// --- the owner's consent ------------------------------------------------------
//
// Each "Piezas can take this over" item is the owner's decision. The AI asks
// one question (`piezas import ask <item>`); the owner's next message is read by
// the UserPromptSubmit hook and recorded only when it is a clear answer. Handing
// the decision back ("use your judgment") is not an answer.

export function importQuestion(data, id) {
  if (id === 'customer-data') {
    return 'Does this app already hold real customer data, such as real bookings or real people\'s details? (yes or no)';
  }
  const items = data.canTakeOver || [];
  if (id === 'all' && items.length >= 1) {
    // One batched question with the recommendation (Spec Part 2, #22).
    return `I recommend moving ${joinWords(items.map((i) => `${i.title.toLowerCase()} (now ${joinWords(i.sources)})`))} to Piezas. `
      + 'Reply yes, or tell me which to keep.';
  }
  const item = items.find((i) => i.id === id);
  if (!item) return null;
  return `${item.title}: your app uses ${joinWords(item.sources)} today. ${item.piezas} Should Piezas take this over? (move or keep)`;
}

export const HANDS_BACK = /\b(your (?:call|choice|judge?ment|decision|recommendation)|you (?:decide|choose|pick|know best)|up to you|whatever you (?:think|want|recommend|prefer|suggest)|(?:i )?(?:don'?t|do not) (?:know|mind|care)|what(?:ever)? (?:do )?you (?:think|recommend|suggest)|you tell me|no preference|either is fine|either way)\b/;
export const SAYS_KEEP = /\b(no|nope|keep|leave|don'?t|do not|stay|not now|not yet)\b/;
export const SAYS_MOVE = /\b(yes|yeah|yep|yup|sure|ok|okay|move|switch|take (?:it |them )?over|go ahead|do it|please do|let'?s do it)\b/;
export const SAYS_HAS_DATA = /\b(yes|yeah|yep|yup|it does|we do|real (?:customers?|people|bookings|data))\b/;
export const SAYS_NO_DATA = /\b(no|nope|not yet|none|only (?:test|sample|fake)|just (?:test|sample|fake)|it doesn'?t|we don'?t)\b/;

// readOwnerAnswer — the owner's reply to the pending question, or null when it
// is not a clear answer (including when they hand the decision back).
export function readOwnerAnswer(questionId, prompt) {
  const said = String(prompt || '').toLowerCase().replace(/[’]/g, "'").replace(/\s+/g, ' ').trim();
  if (!said || HANDS_BACK.test(said)) return null;
  if (questionId === 'customer-data') {
    const plain = said.replace(/\b(?:no|not any|without) real\b/g, 'no');
    const yes = SAYS_HAS_DATA.test(plain);
    const no = SAYS_NO_DATA.test(plain);
    return yes === no ? null : yes ? 'yes' : 'no';
  }
  if (questionId === 'all') {
    if (/\b(keep (?:them )?all|keep everything|none of them|leave (?:them|everything|it all))\b/.test(said)) return 'keep';
    const keep = SAYS_KEEP.test(said);
    return SAYS_MOVE.test(said) && !keep ? 'take' : null;
  }
  const move = SAYS_MOVE.test(said);
  const keep = SAYS_KEEP.test(said);
  return move === keep ? null : move ? 'take' : 'keep';
}

// recordOwnerReply — called by the UserPromptSubmit hook. Returns a note for
// the session, or '' when no import question was waiting.
export function recordOwnerReply(root, prompt) {
  const current = readImportState(root);
  const pending = current?.pendingQuestion;
  if (!pending?.id) return '';
  const said = String(prompt || '').toLowerCase().replace(/[’]/g, "'").replace(/\s+/g, ' ').trim();
  const quote = String(prompt || '').trim().slice(0, 200);
  const at = new Date().toISOString();
  const items = current.canTakeOver || [];
  const takeover = pending.id !== 'customer-data';
  // "you decide" / "whatever you think": go with the recommendation (move),
  // recorded as such. Never for the customer-data question.
  // A question ("what do you recommend?") is not handing it back: it is
  // answered, then asked again.
  const handsBack = takeover && HANDS_BACK.test(said) && !said.includes('?');
  let choices = null; // id -> 'take' | 'keep'
  if (handsBack) {
    choices = Object.fromEntries((pending.id === 'all' ? items : items.filter((i) => i.id === pending.id)).map((i) => [i.id, 'take']));
  } else if (pending.id === 'all') {
    choices = readBatchAnswer(items, said);
  }
  const answer = choices ? null : readOwnerAnswer(pending.id, prompt);
  if (!choices && !answer) {
    writeImportState(root, { ...current, pendingQuestion: null });
    return 'The owner\'s reply was not a clear answer to the question, so nothing was recorded. It is their decision: '
      + 'give your recommendation in one sentence, then run `piezas import ask` again and ask plainly. Do not decide for them.';
  }
  const via = handsBack ? 'recommendation' : 'owner-reply';
  const consent = { question: pending.id, answer: choices ? choices : answer, said: quote, at, via, ...(handsBack ? { decidedVia: 'recommendation' } : {}) };
  let data = { ...current, pendingQuestion: null, consents: [...(current.consents || []), consent], decidedAt: at };
  if (pending.id === 'customer-data') {
    data = { ...data, customerData: answer, customerDataVia: 'owner', dataMigration: answer === 'yes' ? 'later' : null };
  } else {
    data = {
      ...data,
      canTakeOver: items.map((item) => {
        const choice = choices ? choices[item.id] : (pending.id === 'all' || item.id === pending.id ? answer : undefined);
        return choice ? { ...item, choice, decidedBy: 'owner', ...(handsBack ? { decidedVia: 'recommendation' } : {}) } : item;
      }),
    };
  }
  writeImportState(root, data);
  const what = pending.id === 'customer-data'
    ? `whether the app holds real customer data: ${answer}`
    : choices
      ? Object.entries(choices).map(([id, c]) => `${id}: ${c === 'take' ? 'move to Piezas' : 'keep as is'}`).join(', ')
      : `${pending.id}: ${answer === 'take' ? 'move to Piezas' : 'keep as is'}`;
  if (handsBack) return `The owner left it to you, so your recommendation is recorded (${what}), marked as their "go with the recommendation". Tell them in one sentence, then continue.`;
  return `The owner answered, and it is recorded (${what}). Continue with the next question, or show the plan if all are answered.`;
}

// readBatchAnswer — the owner's reply to "I recommend moving A, B, C to
// Piezas. Reply yes, or tell me which to keep.": { id: 'take'|'keep' } for
// every item, or null when it is not clear (then they are asked again).
// The reply is read clause by clause (split at , ; . "but", "except", and an
// "and" before a verb); each clause's verb applies to the items it names:
//   "yes" / "sure, move them"                  -> all move
//   "keep all" / "leave them"                  -> all stay
//   "yes, but keep email" / "move everything except email" / "keep email"
//                                              -> email stays, the rest move
//   "only records" / "move just records, not email" -> records moves, the rest stay
//   "records: move, email: keep, sign-in: move"    -> each as named
// An item read both ways, a negated keep ("don't keep anything"), a clause
// with words that are not about the choice, or an item left unnamed with no
// "yes", "the rest", "everything" or "only" to settle it: null. A hedge ("not
// sure", "not yet", "let me think", any question) is never an answer.
export const BATCH_HEDGE = /\?|\b(?:not sure|unsure|not certain|not yet|let me think|i'?ll think|think about|thinking|maybe|perhaps|hmm+|wait|hold on|later|i guess|dunno|no idea|not decided|undecided)\b/;
const BATCH_YES_WORDS = new Set(['yes', 'yeah', 'yep', 'yup', 'sure', 'ok', 'okay', 'please', 'move', 'them', 'all', 'it', 'everything', 'go', 'ahead', 'do', 'that', 'sounds', 'good', 'great', 'fine', "let's", 'lets', 'to', 'piezas', 'of', 'the', 'take', 'over', 'switch', 'thanks', 'thank', 'you', 'absolutely', 'definitely', 'agreed', 'and']);
const BATCH_FILLER = new Set([...BATCH_YES_WORDS, 'a', 'an', 'for', 'now', 'too', 'can', 'should', 'both', 'rest', 'others', 'other', 'else', 'ones', 'one', 'out', 'but',
  'keep', 'keeping', 'leave', 'leaving', 'stay', 'stays', 'staying', 'moving', 'moved', 'switching', 'migrate', 'not', 'no', "don't", 'dont', 'never',
  'except', 'apart', 'from', 'than', 'without', 'only', 'just', 'as', 'is', 'are', 'be', 'we', 'i', 'will', "i'd", 'would', 'like', 'want', 'where', 'they', 'its', "it's", 'their', 'current', 'nothing', 'none', 'anything', 'right']);
const BATCH_MAX_WORDS = 8;
const BATCH_MAX_REPLY_WORDS = 30;
const BATCH_KEEP_VERB = /\b(?:keep|keeping|leave|leaving|stays?|staying)\b/;
const BATCH_MOVE_VERB = /\b(?:move|moving|moved|switch|switching|migrate|take (?:it |them )?over|yes|yeah|yep|yup|sure|ok|okay|go ahead|do it|absolutely|definitely|agreed)\b/;
const BATCH_NEGATE = /\b(?:not|no|don'?t|do not|never|except|without|apart from|other than)\b/;
const BATCH_GROUP_ALL = /\b(?:everything|all|them|both)\b/;
const BATCH_GROUP_REST = /\b(?:the rest|the others|everything else|the other ones|others)\b/;
const BATCH_NOTHING = /\b(?:nothing|none|anything)\b/;

// itemMentioned — the reply names this item (its id, title, or the title's
// first word).
const nameRe = (w) => new RegExp(`(^|[^a-z])${w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![a-z])`, 'g');
const itemNamePatterns = (item) => [item.title.toLowerCase(), item.id, item.title.toLowerCase().split(/\s+/)[0]]
  .filter((w) => w && w.length > 2)
  .map(nameRe);
export function itemMentioned(item, text) {
  return itemNamePatterns(item).some((re) => { re.lastIndex = 0; return re.test(text); });
}

// namedItems — the items a clause names, and the clause with their names
// taken out. Whole names (titles and ids) first, longest first, each taken
// out before shorter ones are looked for ("email reminders" is not also
// "email"). A title's first word counts only for what is left, and only when
// no other item's title starts with it: a first word several items share
// ("email" for Email reminders and Email digests) is ambiguous.
export function namedItems(clause, items) {
  let rest = String(clause);
  const found = [];
  const whole = items
    .flatMap((i) => [[i, i.title.toLowerCase()], [i, String(i.id ?? '').toLowerCase()]])
    .filter(([, w]) => w && w.length > 2)
    .sort((a, b) => b[1].length - a[1].length);
  for (const [item, w] of whole) {
    if (!nameRe(w).test(rest)) continue;
    if (!found.includes(item)) found.push(item);
    rest = rest.replace(nameRe(w), '$1 ');
  }
  const byFirst = new Map();
  for (const item of items) {
    const first = item.title.toLowerCase().split(/\s+/)[0];
    if (first && first.length > 2) byFirst.set(first, [...(byFirst.get(first) ?? []), item]);
  }
  for (const [first, sharing] of byFirst) {
    if (!nameRe(first).test(rest)) continue;
    if (sharing.length > 1) return { found, rest, ambiguous: true };
    if (!found.includes(sharing[0])) found.push(sharing[0]);
    rest = rest.replace(nameRe(first), '$1 ');
  }
  return { found, rest, ambiguous: false };
}

export function readBatchAnswer(items, said) {
  const text = String(said || '').toLowerCase().replace(/[’]/g, "'").replace(/\s+/g, ' ').trim();
  if (!items.length || !text || HANDS_BACK.test(text) || BATCH_HEDGE.test(text)) return null;
  if (/^(?:no|nope|nah)\b/.test(text)) return null;
  // A reply that stops mid-thought ("yes - but", "yes, except").
  if (/(?:^|\s)(?:but|except|and|not|apart from|other than)\s*[-—–.,!;:]*$|[-—–]\s*$/.test(text)) return null;
  const words = text.replace(/[^a-z0-9' -]+/g, ' ').split(/\s+/).filter(Boolean);
  if (words.length > BATCH_MAX_REPLY_WORDS) return null;
  // "both" says which only when there are exactly two.
  if (/\bboth\b/.test(text) && items.length !== 2) return null;
  const all = (c) => Object.fromEntries(items.map((i) => [i.id, c]));
  const mentioned = (part) => namedItems(part, items).found;
  // The whole reply as a plain yes: short, and nothing in it but yes words.
  if (!mentioned(text).length && words.length <= BATCH_MAX_WORDS && words.every((w) => BATCH_YES_WORDS.has(w)) && !BATCH_NEGATE.test(text)) {
    return SAYS_MOVE.test(text) ? all('take') : null;
  }

  // Clauses.
  let t = text.replace(/:/g, ' ');
  t = t.replace(/\b(all|everything|them) but\b/g, '$1, except');
  t = t.replace(/\s+(?=(?:except|apart from|other than)\b)/g, ', ');
  t = t.replace(/\bbut\b/g, ',');
  t = t.replace(/\s+(?:and|then)\s+(?=(?:keep|leave|move|switch|don'?t|do not|not)\b)/g, ', ');
  const clauses = t.split(/[,;.!]+|\s[-—–]+\s|[—–]/).map((c) => c.trim()).filter(Boolean);

  const picked = new Map(); // id -> 'take' | 'keep'
  let strong = null; // the rest, from "the rest" / "everything" / "only"
  let weak = null; // the rest, from a plain "yes" in the reply
  let explicitKeep = false;
  let anyTake = false;
  const setStrong = (c) => { if (strong && strong !== c) return false; strong = c; return true; };
  // The last "all"/"everything"/"the rest" clause's choice: an "except X"
  // right after it is the other choice for X ("keep all except email": email
  // moves; "move everything except email": email stays).
  let groupChoice = null;
  for (const clause of clauses) {
    if (BATCH_NOTHING.test(clause)) return null;
    const { found: named, rest, ambiguous } = namedItems(clause, items);
    if (ambiguous) return null;
    if (rest.replace(/[^a-z0-9' -]+/g, ' ').split(/\s+/).filter(Boolean).some((w) => !BATCH_FILLER.has(w))) return null;
    const exceptClause = /^(?:except|apart from|other than)\b/.test(clause) && groupChoice !== null;
    const keepVerb = BATCH_KEEP_VERB.test(rest);
    const negated = BATCH_NEGATE.test(exceptClause ? rest.replace(/^\s*(?:except|apart from|other than)\b/, ' ') : rest);
    const moveVerb = BATCH_MOVE_VERB.test(rest);
    const only = /\b(?:only|just)\b/.test(rest);
    let polarity = null;
    if (exceptClause) {
      if (!named.length || keepVerb || moveVerb || negated) return null;
      polarity = groupChoice === 'take' ? 'keep' : 'take';
    } else if (keepVerb && (negated || moveVerb)) return null;
    else if (keepVerb) polarity = 'keep';
    else if (negated) polarity = 'keep';
    else if (moveVerb) polarity = 'take';
    if (named.length) {
      if (!polarity) {
        if (!only) return null;
        polarity = 'take';
      }
      for (const item of named) {
        if (picked.has(item.id) && picked.get(item.id) !== polarity) return null;
        picked.set(item.id, polarity);
      }
      if (polarity === 'take') anyTake = true;
      if (keepVerb) explicitKeep = true;
      if (only) {
        // "only email no" says nothing clear about the rest.
        if (polarity === 'keep' && !keepVerb) return null;
        if (!setStrong(polarity === 'take' ? 'keep' : 'take')) return null;
      }
    } else if (BATCH_GROUP_REST.test(rest) || BATCH_GROUP_ALL.test(rest)) {
      if (!setStrong(polarity ?? 'take')) return null;
      groupChoice = polarity ?? 'take';
      if ((polarity ?? 'take') === 'take') anyTake = true;
    } else if (polarity === 'take') {
      weak = 'take';
    } else if (polarity === 'keep') {
      // "keep", "no", "please don't" with nothing named: not clear.
      return null;
    }
  }
  // "keep email" alone answers "tell me which to keep": the rest move.
  const others = strong ?? weak ?? (explicitKeep && !anyTake ? 'take' : null);
  const out = {};
  for (const item of items) {
    const c = picked.get(item.id) ?? others;
    if (!c) return null;
    out[item.id] = c;
  }
  return out;
}

// importNote — what a session needs to know about an imported app, by step.
export function importNote(root, phase) {
  const imported = readImportState(root);
  if (!imported) return '';
  const head = "This app was IMPORTED from the owner's existing code (a copy; their original folder is untouched).";
  if (phase === 'discover') {
    return [
      head,
      'Do not interview from scratch. Run `piezas import scan`, read the code, and draft the description (SPEC.md) from what the app actually does.',
      'Mark each requirement "(found in your code: <file>)". Ask the owner only about what the code cannot tell you (who uses it, what matters most), one question at a time.',
      'Then show the short card and the two lists in plain words (must move to Piezas; Piezas can take this over).',
      "The owner decides the services in one reply: run `piezas import ask all` and ask exactly the one question it prints (\"I recommend moving ... to Piezas. Reply yes, or tell me which to keep.\"), then wait for their reply.",
      'Their own reply is recorded automatically; you cannot record a choice for them. If they hand it back ("you decide", "whatever you think"), your recommendation is recorded as their choice. A question or a hedge ("not sure", "let me think") is not an answer: answer it in one sentence and ask again.',
      imported.customerData === 'no' && imported.customerDataVia === 'scan'
        ? `Piezas found no database or server code, so it noted "no real customer data". Tell the owner once, in these words: "${NO_DATA_STORE_LINE}" If they say it is wrong, run \`piezas import ask customer-data\` and ask it.`
        : imported.customerData == null
          ? 'Then ask "Does this app already hold real customer data?" (`piezas import ask customer-data`). "You decide" is not an answer to that one: ask it plainly.'
          : '',
      'When everything is answered, run `piezas phase advance` and show the preview; never ask "Want to see it?".',
    ].filter(Boolean).join(' ');
  }
  if (phase === 'mock') {
    const lines = [head, 'The preview is their own app running, with sample data where it needs settings it does not have yet. Show it and change only what they ask for.'];
    const gaps = importGaps(root, 'mock');
    if (gaps.length) lines.push(`Still to ask the owner before building: ${gaps.map((g) => g.message).join('; ')}.`);
    return lines.join(' ');
  }
  if (phase === 'build') {
    const plan = importPlanLines(imported);
    return plan.length
      ? [head, 'Build plan (the work of this step; the app cannot go live until it is done):', ...plan].join('\n')
      : head;
  }
  return '';
}

// --- inside an AI tool ------------------------------------------------------

// agentHost — which AI tool's shell runs this command, by name (Claude Code or
// Codex), for naming the tool in hints. PIEZAS_AGENT_HOST can only turn the
// detection ON (tests name a host); no value of it turns it off.
export function agentHost(env = process.env) {
  if (['claude-code', 'codex'].includes(env.PIEZAS_AGENT_HOST)) return env.PIEZAS_AGENT_HOST;
  // Codex first: its variables are set per command, while CLAUDECODE is also
  // inherited by anything started from a Claude Code session.
  if (Object.keys(env).some((key) => /^CODEX_(SANDBOX|THREAD_ID|SESSION_ID|MANAGED_BY)/.test(key))) return 'codex';
  if (env.CLAUDECODE === '1' || env.CLAUDE_CODE_ENTRYPOINT) return 'claude-code';
  return null;
}

// aiHostMarker — the first variable that says an AI tool (any of them, not
// only the two Piezas has hooks for) runs this shell, or null.
export function aiHostMarker(env = {}) {
  const named = agentHost(env);
  if (named) return named;
  // CLAUDE_CODE_SSE_PORT alone is an editor's own terminal (the IDE
  // extension), where the owner types; the AI's shell sets CLAUDECODE.
  const keys = Object.keys(env).filter((key) => String(env[key] ?? '') !== '');
  const key = keys.find((k) => /^(?:CLAUDECODE|CLAUDE_CODE_ENTRYPOINT|CODEX_(?:SANDBOX|THREAD_ID|SESSION_ID|MANAGED_BY|CI)|CURSOR_|WINDSURF_|CODEIUM_|AIDER_|COPILOT_AGENT|GITHUB_COPILOT_|VSCODE_COPILOT|GEMINI_CLI|CLINE_|ROO_CODE|OPENCODE|AMP_|AI_AGENT$|AGENT$|AGENT_ID$|AGENT_SESSION)/.test(k));
  if (key) return key;
  const term = String(env.TERM_PROGRAM ?? '').toLowerCase();
  if (/cursor|windsurf|kiro|zed-agent/.test(term)) return `TERM_PROGRAM=${term}`;
  return null;
}

// The process chain above this one: a few levels of `ps`, read once.
const AI_PROCESS = /^(?:claude|codex|cursor-agent|aider|gemini|opencode|windsurf)(?:\.js|\.exe)?$/i;
let parentChainCache;
function parentChain() {
  if (parentChainCache !== undefined) return parentChainCache;
  const chain = [];
  let pid = process.ppid;
  try {
    for (let level = 0; level < 6 && pid > 1; level += 1) {
      const line = String(execSync(`ps -o ppid=,comm=,args= -p ${Number(pid)}`, { encoding: 'utf-8', stdio: ['ignore', 'pipe', 'ignore'], timeout: 2000 })).trim();
      const m = /^(\d+)\s+(.*)$/.exec(line);
      if (!m) break;
      chain.push(m[2]);
      pid = Number(m[1]);
    }
  } catch { /* no ps (Windows), or the chain ended */ }
  parentChainCache = chain;
  return chain;
}
function aiInChain(chain) {
  for (const entry of chain) {
    const words = String(entry).split(/\s+/).filter(Boolean);
    const names = words.slice(0, 3).map((w) => w.split(/[\\/]/).pop());
    if (names.some((n) => AI_PROCESS.test(n))) return entry.slice(0, 80);
    if (/\bnode\b/.test(names[0] || words[0] || '') && /piezas\.mjs\b/.test(entry)) return entry.slice(0, 80);
  }
  return null;
}

// The test harness (tests/helpers/no-ai-tool.js) replaces what this process
// sees of the process chain and the terminal (and, when a test names them,
// its own variables).
// Only code loaded into the process can set it; no variable or flag can.
const AI_PROBE = Symbol.for('piezas.aiToolProbe');

// aiToolSignals — every sign that an AI tool runs this command: a host
// variable (in the env given or this process's own), an AI tool in the process
// chain, or no terminal on stdin. Any one is enough; clearing one variable
// leaves the others.
export function aiToolSignals(env = process.env) {
  const probe = globalThis[AI_PROBE];
  const signals = [];
  const fromEnv = aiHostMarker(env ?? {});
  if (fromEnv) signals.push(`env:${fromEnv}`);
  if (env === undefined) env = process.env;
  const own = probe?.env ?? process.env;
  const fromOwn = own === env ? null : aiHostMarker(own);
  if (fromOwn && fromOwn !== fromEnv) signals.push(`env:${fromOwn}`);
  // A test names a host on this process to turn the detection on.
  const named = agentHost({ PIEZAS_AGENT_HOST: process.env.PIEZAS_AGENT_HOST });
  if (named && !signals.length) signals.push(`env:${named}`);
  const chain = probe ? probe.chain ?? [] : parentChain();
  const inChain = aiInChain(chain);
  if (inChain) signals.push(`process:${inChain}`);
  const tty = probe ? probe.stdinTTY !== false : Boolean(process.stdin.isTTY);
  if (!tty) signals.push('stdin:not-a-terminal');
  return signals;
}

// agentSurface — where the AI tool in use runs, for the steps in hints: its
// desktop app (buttons, no typed commands such as /hooks) or a terminal.
// { host, app }: host as agentHost; app true (the app), false (a terminal) or
// null (cannot tell). Wording only: nothing is allowed or refused by it.
// Claude Code names its entry point (cli, claude-desktop, claude-desktop-3p).
// Codex names who started it (the app: 'Codex Desktop', 'codex_work_desktop';
// an editor extension: 'codex_vscode', which is neither, so nothing more is
// read). Otherwise the nearest codex in the process chain decides, read from
// the first words of each entry as aiInChain reads them (macOS ps cuts the
// executable column to 16 characters; the full path follows in the command
// line): the app runs the Codex it bundles (.../ChatGPT.app/.../CodexCLI.app/
// ...); on macOS, where that layout is known, one anywhere else is the
// terminal one, even when its terminal is the app's own panel. No codex in the
// chain: cannot tell.
const CODEX_APP_PATH = /\/(?:ChatGPT|Codex)\.app\//;
export function agentSurface(env = process.env) {
  const host = agentHost(env);
  if (host === 'claude-code') {
    const entry = String(env.CLAUDE_CODE_ENTRYPOINT ?? '');
    if (entry === 'cli') return { host, app: false };
    if (/^claude-desktop/.test(entry)) return { host, app: true };
    return { host, app: null };
  }
  if (host === 'codex') {
    const originator = String(env.CODEX_INTERNAL_ORIGINATOR_OVERRIDE ?? '');
    if (originator !== '') return { host, app: /desktop/i.test(originator) ? true : null };
    if (String(env.CODEX_APP_TOOLS_PIPE_PATH ?? '') !== '') return { host, app: true };
    const probe = globalThis[AI_PROBE];
    const chain = (probe ? probe.chain ?? [] : parentChain()).map(String);
    const platform = probe?.platform ?? process.platform;
    for (const entry of chain) {
      const words = entry.split(/\s+/).filter(Boolean).slice(0, 3);
      const exe = words.find((w) => /^codex(?:\.exe)?$/i.test(w.split(/[\\/]/).pop()));
      if (!exe) continue;
      if (CODEX_APP_PATH.test(exe)) return { host, app: true };
      return { host, app: platform === 'darwin' ? false : null };
    }
    return { host, app: null };
  }
  return { host: null, app: null };
}

// What an owner-only command prints when an AI tool runs it, whatever
// spelling got it past the guard.
export const OWNER_ONLY_IN_AI_TEXT =
  'Only the owner can do this, in their own terminal outside the AI tool, or on the app page in the Piezas console. Nothing was changed. ' +
  '(For the AI: do not try another way; tell the owner in one sentence where they can do it.)';

// stdinIsTerminal — a terminal on stdin (what the test harness says, in tests).
export function stdinIsTerminal() {
  const probe = globalThis[AI_PROBE];
  return probe ? probe.stdinTTY !== false : Boolean(process.stdin.isTTY);
}

// aiHostSignals — the signs that name an AI tool (a variable, the process
// chain), without the terminal: a run with no terminal and none of these is
// unattended (CI, or a build server that sets no CI variable).
export function aiHostSignals(env = process.env) {
  return aiToolSignals(env).filter((s) => s !== 'stdin:not-a-terminal');
}

// inAiTool — true when any signal says an AI tool runs this command.
export function inAiTool(env = process.env) {
  return aiToolSignals(env).length > 0;
}

// The plugin runs its own copy of this file from <plugin>/vendor/; next to it
// sit the plugin manifests. A CLI from npm has none.
export function runningFromPlugin() {
  const root = join(__dirname, '..');
  return existsSync(join(root, '.claude-plugin', 'plugin.json')) || existsSync(join(root, '.codex-plugin', 'plugin.json'));
}

export const HOST_NAMES = { 'claude-code': 'Claude Code', codex: 'Codex' };
export const PLUGIN_HINT = {
  'claude-code': {
    cli: 'In Claude Code, type /plugin, find Piezas and install it, then start a new session in this folder.',
    app: 'In the Claude app, click + next to the prompt box, choose Add plugins, find Piezas and install it, then start a new session in this folder.',
  },
  codex: {
    cli: 'In Codex, type /plugins, find Piezas and install it, then open /hooks and trust Piezas.',
    app: 'In the Codex app, open Plugins in the sidebar, find Piezas and click Install, then open Settings, then Hooks, and click Trust all.',
  },
};

// pluginHintLines — how to install the plugin where the tool runs: one line
// when that is known, both (each with its label) when it is not.
export function pluginHintLines(host, app) {
  return PLUGIN_HINT[host] ? surfaceSteps(PLUGIN_HINT[host], host, app) : [];
}

